window.harnessChunks["rows-f0edfbb798f8fe32.js"]=["<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-17T19:15:26+03:00\"><th scope=\"row\"><a href=\"https://github.com/aaif-goose/goose\" target=\"_blank\" rel=\"noopener\">Goose</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/aaif-goose/goose/tree/50666ae0b9a51e260b52b7efbab2e4e020346e94\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 50666ae0b9a51e260b52b7efbab2e4e020346e94\">50666ae &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: the standard runtime autonomously selects and executes actions/tools within configured bounds and iterates from results.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: no first-party S2 witness was established. The orchestrator permits top-level cross-session messages and permits delegated subagents to message siblings with the same parent, but generic communication does not identify a specific inter-S1 interference, conflict or oscillation together with a relation that attenuates it and feeds the result back into later S1 behavior. Subagent/fork support remains delegation rather than sufficient S2 evidence.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the first-party orchestrator mode gives the autonomous top-level Goose agent a whole-system current view across sessions (listsessions / viewsession) and actual intervention authority over current commitments and operational capacity (startagent, sendmessage, interruptagent). These tools are directly model-visible and their effects are closed by the runtime; once the supported mode is enabled, a developer does not need to compose a separate autonomous actor, S3 decision authority, or closure loop. defaultenabled: false and hidden: true do not convert an otherwise closed agent-owned mode into C. The decisive evidence was already present at the accepted review ref, making this a same-ref correction rather than a new-ref architectural change.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no alternative, sufficiently independent complementary audit path with materially different access to operational reality was established. Session viewing is part of the same S3 current-control surface, not a distinct audit relation.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: context management, retries and task reasoning concern current execution; no distinct externally and prospectively oriented intelligence loop that develops adaptation options and returns them into current capability was found.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: system prompts, permissions, extensions and runtime configuration remain developer/user supplied rather than an autonomous legitimate identity/ultimate-policy decision path.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c18ecd44bdd2a63ce0893a114d25f5d3cc75a76a/assessments/goose.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c18ecd44bdd2a63ce0893a114d25f5d3cc75a76a\">c18ecd4 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-19T18:08:39+03:00\"><th scope=\"row\"><a href=\"https://github.com/Onelevenvy/flock\" target=\"_blank\" rel=\"noopener\">Flock</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-19\">2026-09-19</time></td><td class=\"review-ref\"><a href=\"https://github.com/Onelevenvy/flock/tree/2eac827aa803ae2ee8578e401a864e116cd994d3\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 2eac827aa803ae2ee8578e401a864e116cd994d3\">2eac827 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously perform environment-facing task work through an iterative model/tool loop and return resulting observations into subsequent action selection. - Disturbance / variety regulated: heterogeneous user requests, changing local/project state, model responses, tool outputs/errors, sandbox/browser/process state and other execution observations requiring context-sensitive next actions. - Decisive decision or feedback right: select the next tool/action from current messages and tool results, then decide whether another operational action is needed or the task/run can terminate. - Decision owner: the active first-party Flock agent loop, including agent nodes used inside declarative workflows. - Supporting / enforcement mechanisms: AgentEngine::run, Flock&#39;s modelrequest/calltools graph, tool registry/executor, sandbox creation, checkpoint state, retries/timeouts, iteration limits and workflow state transport. - Closure path: task/messages/environment state → agent model selects a tool/action → first-party Flock tool/runtime executes it → tool result or changed environment returns into agent messages/state → agent chooses the next action or terminates. - Boundary reachability: this is the core shipped flock-agent path used by ordinary runs; workflow agent nodes expose the same class of bounded autonomous tool loop in the supported declarative workflow surface. - Why this is / is not agent-owned: deterministic graph/tool machinery transports and enforces execution, but it does not choose the context-sensitive next operational action; removing the model-driven agent leaves no owner of that S1 discretion. - Evidence: crates/flock-agent/src/engine/run/run.rs, crates/flock-agent/src/graph/builder.rs, crates/flock-workflow/src/nodes/agent.rs. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 coordination path is established at the reviewed recursion. - Disturbance / variety regulated: not established; workflows can contain multiple operational agent nodes, but the reviewed shipped mechanisms do not identify a specific actual or structurally evidenced interference, conflict or oscillation among those S1 units that a coordination relation is designed to attenuate. - Decisive decision or feedback right: no S2-specific actor is shown choosing or revising a coordination response to cross-S1 disturbance. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: graph edges, conditional routing, fan-out to multiple successors, shared workflow state, checkpointing, retries/timeouts and scheduler execution. - Closure path: these mechanisms move and sequence state/work among nodes, but no interference → attenuation decision → changed subsequent S1 behavior closure is evidenced. - Why this is / is not agent-owned: individual agent nodes own their local operational choices; graph topology and scheduler semantics are deterministic/user-authored. Neither fact establishes autonomous coordination of a concrete inter-S1 disturbance. - Evidence: crates/flock-workflow/src/builder.rs, crates/flock-workflow/src/nodes/agent.rs, crates/flock-agent/src/graph/mod.rs. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no whole-system current-control function is established in the reviewed standard distribution. - Disturbance / variety regulated: workflow progress, node failures, retries, timeouts and branch routing are regulated mechanically, but no first-party actor is shown regulating current shared resources, commitments, priorities or constraints on behalf of the whole Flock organization. - Decisive decision or feedback right: no shipped actor has both a whole-system current view and discretionary authority to revise relevant organization-wide commitments/resources/priorities/interventions. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: workflow scheduler/compiled graph, checkpoints, retries/timeouts, cancellation state, workflow event sink, cron/headless execution controls and per-session approval state. - Closure path: these mechanisms close execution and error-handling transitions according to configured topology/policy, not a discretionary whole-system S3 control conversation. - Why this is / is not agent-owned: agent nodes select local task actions, while the workflow compiler/scheduler enforces configured structure. Neither worker selection nor deterministic current-state execution supplies the broader S3 decision right. - Evidence: crates/flock-workflow/src/builder.rs, crates/flock-workflow/src/nodes/common.rs, crates/flock-agent/src/engine/run/run.rs. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material complementary operational-audit path is established for the current S1/S3 control boundary. - Disturbance / variety regulated: Flock exposes tool results, workflow events, retries and evaluation utilities, but no reviewed supported path independently challenges an operational unit&#39;s ordinary current-control claim and returns that finding into S3. - Decisive decision or feedback right: none established for S3 at the current-control layer. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: workflow/tool event emission, retries, error state, checkpoints, logs, and grader/comparator/analyzer machinery bundled specifically inside the skill-development evaluation workflow. - Closure path: routine tool/workflow results feed the same operational path; skill-development graders/comparators feed S4 capability adaptation. Neither supplies a complementary current-operations audit channel returning findings to an S3 owner. - Why this is / is not agent-owned: independent graders can judge skill-development trials, but the audited claim there is prospective adaptation quality rather than current S1 operational accountability; moving that mechanism across functions would be a category error. - Evidence: crates/flock-workflow/src/nodes/agent.rs, flock-data/skills/skill-creator/SKILL.md. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: develop and test reusable future Flock capability in response to capability needs and externally/future-relevant information, then return the resulting adaptation into the skill surface used by later operation. - Disturbance / variety regulated: a user&#39;s desired capability may not exist or an existing skill may perform poorly; relevant documentation, similar skills, best practices, edge cases, model/tool behavior, evaluation failures and changing triggering behavior create future-facing distinctions that should change the reusable capability. - Decisive decision or feedback right: choose the concrete skill design and revisions—workflow/instructions/resources, evaluation cases/assertions, changes suggested by trial transcripts/benchmarks, reusable helper scripts and triggering-description changes—then decide whether further adaptation iterations are warranted within the user&#39;s stated objective/feedback. - Decision owner: the active first-party Flock agent following the shipped skill-creator adaptation procedure. The user/Parent supplies the capability goal, may confirm intent/evals and can stop or accept the loop, but the agent develops, tests and revises the adaptation options rather than merely persisting a user-authored artifact. - Supporting / enforcement mechanisms: packaged skill-creator instructions/resources; research through available tools/MCP where useful; with-skill versus baseline trial runs; graders/comparators/analyzer; benchmark aggregation; human feedback; description-optimization loop; filesystem skill format; skill loader/discovery and packaged application skill resources. - External distinction: relevant external documentation, similar skills, best practices, available tool/model behavior and user-environment requirements can expose capability gaps or better approaches that are not contained in the current skill alone. - Future / prospective distinction: the loop asks whether a reusable skill will handle representative future tasks and trigger appropriately, comparing candidate capability against baselines/previous versions and held-out or expanded evaluations rather than merely repairing the current turn. - Adaptation option generated: a new or revised reusable SKILL.md plus supporting scripts/resources, evaluation design and triggering description selected by the agent from those distinctions and trial results. - Path back into current capability / S3: the selected skill is written or packaged into Flock-readable user/project/workspace/install skill locations; flock-skills subsequently discovers/loads it into later agent contexts, changing the capability available to present operational runs. - Closure path: capability need + relevant external/future distinctions → agent researches/designs a reusable skill option → with-skill/baseline trials and feedback expose performance distinctions → agent revises the skill/description/resources → resulting skill is written/packaged in a Flock-readable skill location → later agent runs load/use the changed capability. - Boundary reachability: skill-creator is under flock-data/skills, those resources are included in the Tauri application bundle, and flock-skills resolves the installed skills resource directory plus user/project skill directories. This is a shipped product capability, not repository-only CI/dogfood. - Why this is / is not agent-owned: user intent and acceptance constrain the adaptation, but the substantive future-capability option generation, diagnosis of trial failures, revision choices and reusable artifact construction are delegated to the agent. Deterministic loaders/eval scripts support and measure the loop rather than owning those adaptation decisions. - Evidence: flock-data/skills/skill-creator/SKILL.md, crates/flock-skills/src/paths.rs, crates/flock-skills/src/discovery.rs, flock-ui/src-tauri/tauri.conf.json. - Basis: structural - Confidence: medium-high - Caveats: generic loading/discovery of already-authored skills alone would not establish S4. Credit depends on the separately shipped adaptation procedure that actively researches/develops/tests/revises a capability and closes it back into the runtime-readable skill surface. Some evaluation branches depend on optional subagent/CLI facilities; the core draft → test/review → revise → persist loop remains explicitly adapted for environments without those facilities.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no identity- or ultimate-policy-level closure is established at the reviewed Flock recursion. - Disturbance / variety regulated: ordinary tool risk and human intervention are regulated, but no evidenced organizational identity/policy issue is routed to a legitimate ultimate authority whose decision returns as non-routine global policy for subsequent operation. - Decisive decision or feedback right: none established for S5. - Decision owner: none established for S5 at this boundary. - Supporting / enforcement mechanisms: ToolApprovalManager, per-session Default/AutoEdit/Yolo modes, per-category “always” approval, sensitive-tool approval, human nodes/ask-human/request-human-assistance, sandbox permissions and workflow configuration. - Closure path: human/tool approvals can approve or deny an ordinary pending action and session modes can change which tool categories auto-approve, but that is task/session authorization rather than identity/ultimate-policy closure balancing current operations and future adaptation. - Why this is / is not agent-owned: approval machinery enforces user/session choices; neither it nor an agent is shown owning legitimate ultimate organizational identity/policy authority. Ordinary human final say over a tool call does not meet S5 by itself. - Evidence: crates/flock-core/src/ipcinterface/approval.rs, crates/flock-workflow/src/nodes/agent.rs, crates/flock-tools/src/tools/builtin/askhuman.rs, crates/flock-tools/src/tools/sandbox/requesthumanassistance.rs. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c8624b55eaa098004a856ac116b7881495866f8f/assessments/flock.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c8624b55eaa098004a856ac116b7881495866f8f\">c8624b5 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-21T17:11:20Z\"><th scope=\"row\"><a href=\"https://github.com/xerrors/Yuxi\" target=\"_blank\" rel=\"noopener\">Yuxi</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-21\">2026-09-21</time></td><td class=\"review-ref\"><a href=\"https://github.com/xerrors/Yuxi/tree/86c67dc41249c3c9cad9e976fd8a006194d39a76\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 86c67dc41249c3c9cad9e976fd8a006194d39a76\">86c67dc &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform user-directed knowledge, analysis and artifact-producing work through a first-party model/tool execution loop. - Disturbance / variety regulated: heterogeneous user requests, retrieved knowledge, files/workspace state, tool/API results, sandbox execution outcomes, model/tool errors and changing conversation/task context. - Decisive decision or feedback right: select substantive next actions/tools and decide when available operational evidence is sufficient to continue, delegate or return a result. - Decision owner: the running Yuxi model agent. - Supporting / enforcement mechanisms: Yuxi ChatbotAgent, configured runtime tools, composite filesystem/sandbox backend, checkpointer, request/run worker lifecycle, retries, context summarization, Skills/MCP and knowledge integration. - Closure path: persisted request → prepared Yuxi agent graph → model-selected tool/action → first-party execution → ToolMessage/observation → subsequent model decision → final persisted result. - Boundary reachability: the standard Yuxi API/worker path directly instantiates and executes ChatbotAgent; no downstream custom harness is required to obtain the model/tool operational loop. - Why this is / is not agent-owned: LangGraph executes graph mechanics and external providers supply model inference, but the model actor owns the discretionary operational choices while Yuxi owns the executable loop, tools/context and durable run path. - Evidence: ARCHITECTURE.md, backend/package/yuxi/agents/base.py, backend/package/yuxi/agents/buildin/chatbot/graph.py. - Basis: explicit + structural. - Confidence: high. - Caveats: generic LangGraph/DeepAgents capabilities not assembled and exposed by Yuxi are not inherited.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party path establishes attenuation of a concrete interference, conflict or oscillation among at least two distinct Yuxi S1 units. - Disturbance / variety regulated: not established as S2 at the reviewed recursion. - Decisive decision or feedback right: not established for S2. - Decision owner: not established for S2. - Supporting / enforcement mechanisms: child AgentRun lifecycle, same-thread no-concurrent-write rule, FIFO request queues, run leases, shared runtime/workdir, parent cancellation and delegation exist but are not credited as coordination by topology or serialization alone. - Closure path: not applicable. - Why this is / is not agent-owned: the root can manage child commitments, but evidence inspected does not identify a concrete cross-child disturbance and an S2-specific attenuation relation whose feedback changes subsequent child behavior. - Evidence: ARCHITECTURE.md, backend/package/yuxi/agents/middlewares/subagenttask.py. - Basis: structural absence review. - Confidence: high. - Caveats: shared workspaces can create potential interaction, but potential collision is not evidence that Yuxi ships a concrete S2 attenuation loop.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: regulate the current portfolio of subordinate Yuxi agent commitments during a root-agent run. - Disturbance / variety regulated: incomplete, delayed, failed, unnecessary or still-running subordinate tasks; changing need for specialist work as child results arrive; risk of finalizing while required delegated work remains unresolved. - Decisive decision or feedback right: decide what child work to start, inspect current child status/progress, await results when needed, cancel a child, continue root work in parallel and condition subsequent commitments/finalization on current child state and returned results. - Decision owner: the root Yuxi model agent. - Supporting / enforcement mechanisms: Yuxi SubAgent middleware; durable parent/child AgentRun relation; subagentstart, subagentstatus, subagentcancel, subagentawait; ChatBotState.subagentruns; child ownership verification; cancellation/request services; persistent run/result state. - Closure path: root identifies current need → starts one or more configured subordinate operations → child run state/result returns as ToolMessage plus subagentruns state → root inspects/awaits/cancels/launches further work as current conditions require → subsequent root action/final answer changes accordingly; remaining live children are cancelled when parent ends. - Boundary reachability: standard configured ChatbotAgent construction automatically installs the SubAgent middleware whenever visible/configured Yuxi subagents exist; the root receives the current-control tools directly in its normal model loop. - Whole-system current view: the root graph state accumulates structured summaries for each child run keyed by runid, including current status, agent identity, timing/error/artifact/result fields; explicit status/await calls refresh individual commitments before the root acts. - Current-control decision scope: start new subordinate commitments, continue prior child threads when idle, inspect their progress/results, wait for required completion, cancel no-longer-wanted work and decide whether the root can safely finalize. - Why this is / is not agent-owned: repositories/services enforce ownership and durable state, but the root model decides which current commitments exist and how their live evidence changes ongoing portfolio action. Removing the model leaves lifecycle mechanics but no discretionary whole-run allocation/control decision. - Evidence: backend/package/yuxi/agents/buildin/chatbot/graph.py, backend/package/yuxi/agents/buildin/chatbot/state.py, backend/package/yuxi/agents/middlewares/subagenttask.py, ARCHITECTURE.md. - Basis: explicit + structural. - Confidence: high. - Caveats: this mapping is conditional on the standard supported mode with configured/visible SubAgents; a single-agent configuration still retains S1 but does not instantiate a multi-unit portfolio.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party path establishes a sufficiently independent complementary challenge to operational reality with corrective return into S1/S3. - Disturbance / variety regulated: not established as S3. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: model/tool audit events, Langfuse integration, run/debug timelines, knowledge/RAG evaluation, human tool approval, retries and child status/results all exist but serve ordinary execution, evaluation or parent governance. - Closure path: not applicable. - Why this is / is not agent-owned: child outputs are production inputs to the root, not a structurally independent audit channel; dashboard/evaluation evidence does not by itself exercise corrective operational authority; human approval is Parent intervention rather than S3. - Evidence: ARCHITECTURE.md, backend/package/yuxi/agents/toolapproval.py, backend/package/yuxi/agents/middlewares/subagenttask.py. - Basis: structural absence review. - Confidence: high. - Caveats: a separately configured reviewer subagent could be constructed downstream, but role naming or constructibility is not a shipped independent audit closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party path establishes autonomous or parent-governed prospective environment-facing adaptation of Yuxi organizational capability. - Disturbance / variety regulated: not established as S4. - Decisive decision or feedback right: not established for prospective capability adaptation. - Decision owner: not established for S4. - Supporting / enforcement mechanisms: knowledge/RAG retrieval, persistent checkpoints, user Memory, dynamically activated Skills, configurable models/tools/MCP and reusable agent/subagent definitions broaden available capability but do not themselves decide and integrate a future organizational adaptation from environmental distinctions. - Closure path: not applicable. - Why this is / is not agent-owned: the memory middleware explicitly writes long-term memory only when the user asks it to remember; Skills are selected/configured resources and dynamic activation occurs within the present run. Persistence/reuse is not prospective S4 closure. - Evidence: README.md, backend/package/yuxi/agents/middlewares/memory.py, backend/package/yuxi/agents/middlewares/skills.py. - Basis: structural absence review. - Confidence: high. - Caveats: administrators/users can change knowledge, agent, Skill, MCP and model configuration, but generic external configuration does not establish Parent-governed S4 without a qualifying S4 issue/option/decision/return path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party path establishes identity- or ultimate-policy-level adjudication that closes unresolved present/future tension for the Yuxi organization. - Disturbance / variety regulated: not established as S5. - Decisive decision or feedback right: not established for identity/ultimate policy. - Decision owner: not established for S5. - Supporting / enforcement mechanisms: multi-tenant RBAC, administrator configuration, agent prompts/descriptions, tool approval mode, model/resource visibility and human approvals constrain operation. - Closure path: not applicable. - Why this is / is not agent-owned: these are access/configuration and parent safety controls. The reviewed repository does not establish a function-specific identity/ultimate-policy issue and an authority that adjudicates it and returns the decision into operation. - Evidence: README.md, ARCHITECTURE.md, backend/package/yuxi/agents/toolapproval.py. - Basis: structural absence review. - Confidence: high. - Caveats: super-admin/operator authority is real product governance but does not become VSM S5 without the identity/ultimate-policy organizational function.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/f0e739507a67e4069c7ef24add9a14d2bfcea7ec/assessments/yuxi.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit f0e739507a67e4069c7ef24add9a14d2bfcea7ec\">f0e7395 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-22T22:58:40+03:00\"><th scope=\"row\"><a href=\"https://github.com/AutoCodeRoverSG/auto-code-rover\" target=\"_blank\" rel=\"noopener\">AutoCodeRover</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-22\">2026-10-22</time></td><td class=\"review-ref\"><a href=\"https://github.com/AutoCodeRoverSG/auto-code-rover/tree/585d3e639aeda58ef0b6a151dd1cc2721a94d267\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 585d3e639aeda58ef0b6a151dd1cc2721a94d267\">585d3e6 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: investigate a supplied code issue and produce an applicable candidate patch through autonomous search and code-edit choices. - Disturbance / variety regulated: uncertainty about code locations, incompatible search requests, non-applicable diffs, failed reproduction and regression outcomes. - Decisive decision or feedback right: select iterative search APIs and suspected bug locations, generate patch content, and revise attempts after code/tool feedback. - Decision owner: first-party search/patch model interactions; operator selects provider and issue, while deterministic backends execute code searches and validation. - Supporting / enforcement mechanisms: SearchBackend AST-aware calls, API-call proxy, diff extraction/applicability, optional SBFL and test execution, bounded retries and candidate selection. - Closure path: issue + repository → model-selected code search → returned source context → model-generated patch → applicability/test/reviewer feedback → next patch or output selection. - Boundary reachability: the main source-search/patch path is the default github-issue, local-issue and SWE-bench work mode and does not require the experimental reviewer. - Why this is / is not agent-owned: model-generated search instructions and patch content vary with observed task data; configured round ceilings, tool execution and user-provided issue are supporting restrictions, not owners of those decisions. - Evidence: search selects APIs and consumes outcomes, model-generated applicable patch and feedback, pipeline. - Basis: structural. - Confidence: high for the shipped model/tool/patch control loop; no claim about the patch&#39;s external task success. - Caveats: live model-backed operation was not tested; ordinary validation is opt-in and some tasks fall back to patch-only generation.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: in the experimental reproducer/reviewer mode, dampen conflict between independently proposed issue reproducer and corrective patch by adjudicating which of the two must be revised. - Disturbance / variety regulated: a patch can make a faulty test pass, or a valid patch can seem wrong because the test incorrectly represents the issue; indiscriminate iteration on only one cell would perpetuate mismatch. - Distinct S1 units: TestAgent autonomously proposes executable reproducing tests; PatchAgent autonomously proposes code changes, each with a dedicated model prompt, artifacts and feedback/revision history. - Inter-S1 disturbance: their joint candidate outcome disagrees with the observed buggy/patched reproducer results and issue semantics, with the conflict potentially attributable to either test construction or patch construction. - Attenuating coordination relation: an independent reviewer model is given the issue, both artifacts and original/patched execution evidence and returns separate patch-correct / test-correct judgments and targeted advice. - Feedback into subsequent S1 behaviour: ReviewManager.generator routes patchdecision == NO to PatchAgent.addfeedback and writeapplicablepatchwithfeedback, while testdecision == NO updates TestAgent.addfeedback and writereproducingtestwithfeedback; the resulting artifacts are re-executed on the following round. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the reviewer is explicitly asked to settle which of two distinct operational outputs is defective, and that decision changes which S1 producer receives a corrective instruction. Merely executing tests or selecting the last patch is not the credited S2 relation. - Decisive decision or feedback right: dynamically judge whether to correct the test, patch or both from cross-cell evidence; the Python manager routes the judgment. - Decision owner: first-party model reviewer in the opt-in mode, not the fixed CLI scheduler or a user-assembled external supervisor. - Supporting / enforcement mechanisms: original/patched repro execution, two-sided review JSON, separate feedback histories, bounded review rounds and validation. - Closure path: test + patch candidates → execute both interpretations → reviewer locates mismatch → affected producer receives focused feedback → regenerated test/patch enters next comparison. - Boundary reachability: the first-party SWE-bench --reproduce-and-review switch installs this loop when a valid reproducer exists; it is experimental, off by default, and not exposed for general local/GitHub issue commands. - Why this is / is not agent-owned: the correctness allocation and advice are discretionary reviewer-model output; the manager&#39;s branches only implement the model&#39;s two judgments. This does not imply shared-system scheduling, generic writer-conflict mediation or whole-current governance. - Evidence: flag and scope, mode gate, two-sided reviewer prompt, feedback dispatched to each agent, reproducer feedback memory. - Basis: structural. - Confidence: medium; the narrowly defined test/patch coordination closure is explicit, but no model-run has established effectiveness or a broader autonomous S2. - Caveats: opt-in experimental SWE-bench only; no reproducer means fallback to patch-only generation. The review loop is quality-focused, does not coordinate parallel workers or resource contention, and its S2 interpretation depends on treating the test and patch generators as distinct operational units rather than one monolithic coding S1.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: direct present resource, commitment, priority and accountability trade-offs of multiple operating units for the whole assessed harness. - Disturbance / variety regulated: model/task retries, concurrent batch workloads, failing patch attempts and tool execution time. - Decisive decision or feedback right: none established at an S3-specific organizational level; task grouping, fixed retry limits and patch selection are preset process management. - Decision owner: human CLI/config author and deterministic orchestration, with model decisions local to repair tasks. - Supporting / enforcement mechanisms: ProcessPoolExecutor, group sequencing, overall retry limit, model cycling, validation and generated patch selection. - Closure path: user-supplied task groups → parallel/serial processing → per-issue output; no separate current-wide negotiation/reprioritization and corrective allocation among an accountable whole. - Why this is / is not agent-owned: process limits and ranking candidate patches do not own whole-organization resource/commitment decisions. - Evidence: task group scheduling, bounded attempts and selection. - Basis: structural. - Confidence: high for the bounded first-party negative. - Caveats: a separate operator organization can add current management, but is outside this assessed runtime.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: independently challenge an S3 current-management claim using a complementary route to operational reality, then return findings for corrective control. - Disturbance / variety regulated: potentially false patch-correctness claims and misleading local tests. - Decisive decision or feedback right: no such S3 audit right; the experimental agentreviewer decides whether local code/test artifacts are correct as ordinary repair-loop QA. - Decision owner: model reviewer and deterministic validator under S1/S2 repair production, not a distinct management auditor. - Supporting / enforcement mechanisms: test execution against original/patched code, reviewer feedback JSON, optional regression validation and logs. - Closure path: code/test pair → reviewer/validator → revise task artifacts, not S3 claims → independent operational audit → S3 corrective management return. - Why this is / is not agent-owned: the reviewer is model-owned but its object is the code patch and reproducer, not complementary verification of whole-current S3 management. - Evidence: reviewer&#39;s actual task, manager feedback scope, local patch validation. - Basis: structural. - Confidence: high for task-level QA versus S3 boundary. - Caveats: the term &quot;reviewer&quot; alone does not establish audit ownership at organizational recursion.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: monitor wider future environment, propose adaptive changes and return selected options to current harness capability. - Disturbance / variety regulated: unfamiliar future issue classes, external library changes, provider variation and changing codebases. - Decisive decision or feedback right: no evidenced prospective organizational capability decision; model selection, fault localization and retrieval are for the present issue. - Decision owner: user/developers choose providers, install new methods and maintain the project; the repair model chooses present-task actions. - Supporting / enforcement mechanisms: model alternatives, AST search, issue context, regression feedback, retries and an external paper/benchmark. - Closure path: issue/code evidence → patch for the same issue, or configured provider fallback; not future trend sensing → strategic adaptation → returned capability change. - Why this is / is not agent-owned: solving a previously unseen issue is S1 operational adaptation, not an installed outside-and-then intelligence function. - Evidence: pipeline and model retry, public research and scope statement. - Basis: structural. - Confidence: medium-high for reviewed runtime. - Caveats: external researchers can measure and change future versions, but their decisions are outside the one-run harness boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: settle ultimate purpose and binding identity/policy conflicts for the running organization. - Disturbance / variety regulated: requested edits outside intended scope, provider-policy rejection, task-local constraints and permissible execution. - Decisive decision or feedback right: no first-party ultimate policy/identity decision path; user provides issues/models/options and model produces candidate patches subject to configured guards. - Decision owner: human operator/developer for values and configuration, with external provider policy enforced by provider. - Supporting / enforcement mechanisms: CLI tasks, prompt instructions, errors/exception fallback and test validation. - Closure path: user-supplied goal/config → issue repair attempt; no identity-level disagreement → legitimate ultimate authority → binding policy decision returned to the operating system. - Why this is / is not agent-owned: prompt-level do/don&#39;t rules and fallback on an external content-policy exception do not transfer supreme policy authority to the coding agent. - Evidence: CLI goal and model selection, provider-policy exception fallback, patch prompt scope. - Basis: structural. - Confidence: high for bounded negative at the local runtime. - Caveats: broader project governance and legal restrictions are external arrangements.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/3be8d80335ca7cbb047936f15ea0705c6d94f3dd/assessments/au/autocoderover.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 3be8d80335ca7cbb047936f15ea0705c6d94f3dd\">3be8d80 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-26T23:41:42+03:00\"><th scope=\"row\"><a href=\"https://github.com/OS-Copilot/OS-Copilot\" target=\"_blank\" rel=\"noopener\">OS-Copilot / FRIDAY</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-26\">2026-09-26</time></td><td class=\"review-ref\"><a href=\"https://github.com/OS-Copilot/OS-Copilot/tree/f720af8807e49a92dda64572d2c6bc6c0ac7ee7e\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision f720af8807e49a92dda64572d2c6bc6c0ac7ee7e\">f720af8 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously plan and execute concrete computer/OS/application work needed to satisfy a user task, adapting task-local actions to returned execution state. - Disturbance / variety regulated: heterogeneous user goals, available tools, filesystem/application state, generated-code failures, missing intermediate operations, execution outputs/errors and changing prerequisites within a task. - Decisive decision or feedback right: choose/decompose the next substantive computer actions, generate or select executable tools, interpret returned execution state and decide whether to continue, amend or replan the active task. - Decision owner: first-party model-driven FRIDAY planner/executor/judge path. - Supporting / enforcement mechanisms: tool retrieval, dependency graph/topological ordering, Python/Shell/AppleScript/API execution environments, bounded repair iterations, task state, generated-tool repository and deterministic loop/control plumbing. - Closure path: user task -&gt; model decomposes/selects actions -&gt; generated/retrieved tool executes against OS/application environment -&gt; result/error/filesystem state returns -&gt; model judges/replans/repairs -&gt; changed action executes -&gt; task state updates. - Boundary reachability: quickstart.py and documented examples instantiate FridayAgent, while FridayAgent.run() directly invokes the credited planner/executor/refinement path. - Why this is / is not agent-owned: deterministic code transports state and executes selected code, while substantive task decomposition, tool generation, result judgment, amendment and replanning choices are model-driven. - Evidence: README.md; oscopilot/agents/fridayagent.py; oscopilot/modules/planner/fridayplanner.py; oscopilot/modules/executor/fridayexecutor.py. - Basis: explicit + structural. - Confidence: high. - Caveats: the README notes single-round conversation, but the internal execution of one task is multi-step and result-conditioned; conversational turn count does not break the operational loop.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 path regulating a concrete disturbance between distinct autonomous S1 units is established at the declared FRIDAY-installation recursion. - Disturbance / variety regulated: the planner orders dependencies among subtasks and modules exchange artifacts, but those subtasks/modules are components of one operational agent rather than separately accountable S1 units producing an inter-operation oscillation/interference problem. - Decisive decision or feedback right: none established for inter-S1 coordination. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: dependency graph, topological ordering, prerequisite-result passing, shared tool repository and sequential subtask loop. - Closure path: task decomposition creates ordered work inside S1, but no distinct S1-A/S1-B interaction disturbance -&gt; coordinating judgment -&gt; changed later behavior of those S1 units loop closes. - Why this is / is not agent-owned: sequencing dependencies is operational planning, not evidence of the VSM S2 organizational function. - Evidence: oscopilot/agents/fridayagent.py; oscopilot/modules/planner/fridayplanner.py. - Basis: structural negative search. - Confidence: high. - Caveats: a deployment containing several separately accountable FRIDAY instances could create an S2 problem, but that is a different system-in-focus.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct first-party whole-system current-control function over multiple or separately managed operational units is established. - Disturbance / variety regulated: task-local execution failures, weak outputs and missing prerequisites are regulated, but they are handled inside the same S1 episode that performs the work. - Decisive decision or feedback right: no separate actor is evidenced with authority to form a whole-installation current view and intervene in the present operational organization beyond the active task-local plan/repair loop. - Decision owner: none established for S3; FRIDAY&#39;s planner/judge retains task-local S1 action authority. - Supporting / enforcement mechanisms: in-band judgetool, repair loop, replanning, task graph/status, score threshold and bounded repair count. - Closure path: execution state -&gt; same operational agent judges/repairs/replans -&gt; same task continues; this closes S1 recovery, not a separate management loop over the current whole. - Why this is / is not agent-owned: model-driven replanning is real discretion, but its organizational function is local task execution/recovery rather than whole-system current control. - Evidence: oscopilot/agents/fridayagent.py; oscopilot/modules/executor/fridayexecutor.py; oscopilot/modules/planner/fridayplanner.py. - Basis: structural negative search. - Confidence: high. - Caveats: names such as planner or orchestrating agent are not promoted to S3 without a whole-system current-view/current-control witness.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no first-party independent complementary-audit channel with distinct access/judgment and corrective return is established. - Disturbance / variety regulated: FRIDAY evaluates generated code/output and may repair or replan, but this is ordinary in-band operational verification. - Decisive decision or feedback right: no independent auditor is evidenced with a separate claim-checking path over operational reality. - Decision owner: none established for S3; judgetool uses the ordinary executor module/model configuration inside the same task loop. - Supporting / enforcement mechanisms: LLM judgment prompt, execution result/error/filesystem observations, score threshold and repair/replan path. - Closure path: operation -&gt; same in-band executor/judge evaluates -&gt; same agent repairs/replans -&gt; operation continues; no independent complementary path returns findings to a separate corrective owner. - Why this is / is not agent-owned: semantic judging exists, but independence/complementary access required for S3 is absent. - Evidence: oscopilot/modules/executor/fridayexecutor.py; oscopilot/modules/basemodule.py; oscopilot/agents/fridayagent.py. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: calling the component a judge or critic does not satisfy S3; no separate reviewer/model/provider/evidence channel comparable to an independent audit path is configured by the standard runtime.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: generate and implement prospective reusable computer capabilities from external software/package/demo context so later operational tasks can perform work the current repertoire could not. - Disturbance / variety regulated: capability gaps exposed by unfamiliar software/application domains, new packages/APIs and task classes not covered by the existing generated-tool repository. - Decisive decision or feedback right: choose a prospective course/lesson set for the selected external software/package context and, through lesson execution, generate reusable tools that expand the future action repertoire. - Decision owner: first-party SelfLearner model for course design plus the model-driven FRIDAY lesson execution path that produces qualifying reusable tools. - Supporting / enforcement mechanisms: software/package/demo inputs, prior-course history, model-authored course JSON, SelfLearning.learncourse, ordinary FRIDAY task execution, score threshold, persistent generated-tool files/JSON/Chroma vector database and retriever similarity search. - Closure path: operator identifies a capability domain -&gt; learner reads software/package/demo/prior-course context -&gt; model designs prospective lessons -&gt; FRIDAY executes lessons -&gt; successful generated Python capabilities are persisted -&gt; later ordinary task queries the same repository -&gt; newly learned tool descriptions/code are retrieved and influence execution -&gt; previously unsupported task becomes executable. - Boundary reachability: courselearning.py is a shipped first-party entrypoint documented by the self-learning tutorial; no downstream code changes or custom orchestration are required to create and reuse the adapted capability. - Why this is / is not agent-owned: the operator selects the broad learning target, while the first-party model determines the course/lessons and FRIDAY generates/qualifies the executable tools; deterministic repository code only persists and retrieves those chosen capabilities. - External distinction: software/package context and optional demo-file contents describe capabilities outside FRIDAY&#39;s existing action repertoire; the documented example uses the external openpyxl library and an Excel file. - Future / prospective distinction: the learning mode is explicitly run to acquire tools for later tasks, rather than only repairing the presently failing task; its persisted output survives the learning episode and is queried in subsequent task planning/execution. - Adaptation option generated: a model-authored course of new capability lessons and the reusable generated tools produced by executing those lessons. - Path back into current capability / S3: qualifying tools are written into generatedtools.json, code/description files and the persistent vector index; ordinary FridayRetriever then automatically retrieves them for later S1 task planning/code generation, changing the executable repertoire without repository-source modification. - Evidence: courselearning.py; oscopilot/agents/selflearning.py; oscopilot/modules/learner/selflearner.py; oscopilot/modules/executor/fridayexecutor.py; oscopilot/toolrepository/manager/toolmanager.py; oscopilot/modules/retriever/vectorretriever.py; docs/source/tutorials/selflearning.rst. - Basis: explicit + structural. - Confidence: high. - Caveats: self-learning is a separate supported operating mode rather than automatically triggered from every failed task. That affects invocation, not ownership of the adaptation option once the mode is invoked. The broad learning domain/package remains operator-supplied and is not treated as autonomous S5 policy.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party runtime identity/ultimate-policy adjudication loop is established. - Disturbance / variety regulated: user task, model/provider settings, score/repair limits, available tools and self-learning domain inputs constrain behavior, but they are task/configuration/capability controls rather than organizational identity or ultimate-policy decisions. - Decisive decision or feedback right: none established for defining/reconciling FRIDAY&#39;s identity, ultimate purpose or legitimate highest-level policy under competing operational/adaptation demands. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: environment/configuration, prompts, thresholds, user task/learning inputs and static runtime structure. - Closure path: configuration/task inputs directly constrain S1/S4 behavior; no identity-level issue -&gt; legitimate ultimate authority -&gt; authoritative policy decision -&gt; returned governance loop is evidenced. - Why this is / is not agent-owned: FRIDAY exercises operational and capability-adaptation discretion, but not authority to redefine its own organizational identity or ultimate policy. - Evidence: README.md; oscopilot/modules/basemodule.py; oscopilot/agents/fridayagent.py; courselearning.py. - Basis: structural negative search. - Confidence: high. - Caveats: user-supplied objectives/learning targets are parent inputs, but ordinary task/capability target selection is not S5=P without an identity/ultimate-policy function.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/df12b45707a2cb0c30902dcd8b2df91a67f603c7/assessments/os-copilot.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit df12b45707a2cb0c30902dcd8b2df91a67f603c7\">df12b45 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-12T14:55:12+03:00\"><th scope=\"row\"><a href=\"https://github.com/agentscope-ai/agentscope\" target=\"_blank\" rel=\"noopener\">AgentScope 2.0</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-12\">2026-10-12</time></td><td class=\"review-ref\"><a href=\"https://github.com/agentscope-ai/agentscope/tree/5ff52f877de12d66a30d55af279dd4f42b1590f3\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 5ff52f877de12d66a30d55af279dd4f42b1590f3\">5ff52f8 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Configurable first-party model-directed reasoning/acting tool loop performs user/worker tasks and returns tool/environment feedback. - Disturbance / variety regulated: Unknown task conditions, tool execution responses/errors, context limits and external model results. - Decisive decision or feedback right: Choose goal-specific tool calls, perform actions, interpret outcomes and continue or finish. - Decision owner: AgentScope-configured agent model in the SDK/Service&#39;s direct agent execution mode. - Supporting / enforcement mechanisms: Model adapters, Toolkit, middleware hooks, workspace/sandbox, permission gates, message/session store. - Closure path: User or leader prompt → agent reasoning → selected tool action → tool/environment result → model continuation and final worker report. - Boundary reachability: The published SDK and example Agent Service initialize real AgentScope Agent instances with toolkit/model and feed messages into replystream (README.md; src/agentscope/agent/agent.py; src/agentscope/app/service/chat.py). - Why this is / is not agent-owned: The model selects substantive task acts; host/session middleware only applies technical limits and transport policy. - Evidence: src/agentscope/agent/agent.py; src/agentscope/app/service/chat.py; src/agentscope/tool/toolkit.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S2 / coordination: - State: ? - Function: Candidate team message routing and session locking, but no proven function-specific first-party inter-S1 interference attenuation with returned feedback. - Distinct S1 units: Separately instantiated model-driven members of a first-party TeamRecord, each with its own session/task and message bus. - Inter-S1 disturbance: Potential conflicting simultaneous operations against shared task resources or overlapping workspace targets; the service&#39;s mere presence of separate sessions does not establish the specific disturbance regulation. - Attenuating coordination relation: The observed session lock serializes calls within one session; TeamSay routes messages and avoids misdelivery, but a function-specific inter-member contention/coordination policy has not been demonstrated. - Feedback into subsequent S1 behaviour: Team messages and leader reassignments exist; their connection to mitigation of a particular verified inter-worker conflict remains unproven. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: No positive S2 attribution is made from generic team topology, messaging, per-session locks or leader assignment alone. - Disturbance / variety regulated: Candidate inter-member resource contention, not established as an implemented control target. - Decisive decision or feedback right: Unresolved for interference-specific arbitration among independent worker sessions. - Decision owner: Potential leader or host service, not yet reconstructable for a material S2 relation. - Supporting / enforcement mechanisms: MessageBus, TeamSay, sessionrun lock, team membership constraints, toolkit role filtering. - Why this is / is not agent-owned: No positive S2 owner is credited; the leader sends messages and the service serializes individual session turns, but neither path is proven to own inter-worker interference-specific decisions. - Closure path: Inter-agent messages are delivered; no defensible concrete collision → arbitration → modified workers path established. - Evidence: src/agentscope/app/tool/teamsay.py; src/agentscope/app/service/chat.py; src/agentscope/app/tool/teamcreate.py; src/agentscope/app/service/toolkit.py. - Basis: unknown -\">?</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: Model-led team leader makes current team staffing, delegation, repair and follow-up decisions based on worker reports. - Disturbance / variety regulated: Pending delegated tasks, changed worker outcomes, failures, information gaps and incomplete task progress. - Decisive decision or feedback right: Create a team, select role/worker, assign task, request clarifications and continue work after returned findings. - Decision owner: First-party hosted model leader using TeamCreate/AgentCreate/TeamSay, not a deterministic background task dispatcher. - Supporting / enforcement mechanisms: TeamRecord, role-separated team tools, agent/worker session allocation, message bus, report-enforcing middleware. - Whole-system current view: Leader receives team roster and completion/failure reports of the team it created; no claim of full multi-tenant service-wide control. - Current-control decision scope: Assign current work, change team tasks, re-instruct workers and integrate returned work in the bounded team recursion. - Closure path: Worker performs task and sends mandatory TeamSay report → leader model receives result → chooses follow-up or new task → worker session/action changes. - Boundary reachability: The Agent Service toolkit grants leader-specific team tools in configured leader mode; worker reports are actively enforced by middleware and persisted/routed back to the leader (src/agentscope/app/service/toolkit.py; src/agentscope/app/tool/agentcreate.py; src/agentscope/app/middleware/teammembermiddleware.py). - Why this is / is not agent-owned: The actual choices of child role, scope and continuation are model-generated via shipped team tools; technical message delivery and individual session run locks are merely enforcement. - Evidence: src/agentscope/app/tool/teamcreate.py; src/agentscope/app/tool/agentcreate.py; src/agentscope/app/tool/teamsay.py; src/agentscope/app/middleware/teammembermiddleware.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S3* / direct audit: - State: ? - Function: GoalPipeline provides separate executor/verifier agents and revision feedback, but complete independent operational-artifact challenge path is not established. - Disturbance / variety regulated: False executor goal-completion statements, missing required deliverables. - Decisive decision or feedback right: Verifier returns pass/fail about executor goal and an explanation, which may prompt another executor iteration. - Decision owner: Separately configured verifier Agent, subject to its actual tools/evidence access. - Supporting / enforcement mechanisms: GoalPipeline executor/verifier alternation, structured execution report, structured verification result. - Claim being audited: Executor&#39;s report that it fulfilled the original goal. - Ordinary reporting path: Executor returns a structured report under ExecutionReport. - Complementary access path: The verifier receives original goal plus executor&#39;s text report; supported independently sampled source/tool artifact inspection is not guaranteed by this pipeline contract. - Independence boundary: Distinct Agent object is possible, but materially independent observation from primary operational artifacts is unresolved. - Who acts on findings: Pipeline sends failure feedback back to executor, conditional on the verifier&#39;s structured judgment. - Closure path: Report → verifier model check → pass/fail → continue or return; missing independent observational basis prevents positive state. - Why this is / is not agent-owned: An independent model call is necessary but not sufficient when its only guaranteed input is the producer&#39;s own claim. - Evidence: src/agentscope/pipeline/goalpipeline.py; src/agentscope/app/middleware/teammembermiddleware.py. - Basis: unknown -\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S4 / adaptation: - State: ? - Function: Persistent memory, scheduling and middleware extension may support reuse across future tasks but do not yet establish an outside-and-then capability adaptation decision. - Disturbance / variety regulated: New task conditions, changing knowledge and external user contexts. - Decisive decision or feedback right: No confirmed owner/loop deciding a prospective adaptation option to future team capability. - Decision owner: Unresolved between user, configured agent, memory backend and developer. - Supporting / enforcement mechanisms: Long-term memory middleware, scheduler manager and goal/planning toolkit. - External distinction: External observations may be retained in memory, but this alone is not systemic intelligence. - Future / prospective distinction: Reuse is future-facing in time but not necessarily prospective organizational adaptation. - Adaptation option generated: Not established from the read-only source evidence. - Path back into current capability / S3: Memory/context or schedule modifications can affect future runs; full future intelligence → change is unproven. - Closure path: Captured memory → later prompt is technically supported, but no established S4 choice/feedback. - Why this is / is not agent-owned: Memory retention and schedules are mechanisms, not proof of autonomous or parent S4. - Evidence: src/agentscope/middleware/longtermmemory; src/agentscope/app/manager/scheduler/schedulermanager.py; src/agentscope/tool/task/updatetask.py. - Basis: unknown -\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S5 / identity: - State: ? - Function: Team identities, access/permission rules and human confirmations exist without established ultimate-policy identity decision/return loop at the bounded team recursion. - Disturbance / variety regulated: Permissions over tools, resource access, multi-tenant rights and delegation. - Decisive decision or feedback right: The human/application owner sets permission rules and may approve actions, but ultimate organizational identity/policy closure is unresolved. - Decision owner: User/app role policies; not automatically a first-party agent policy controller or a qualified parent S5. - Supporting / enforcement mechanisms: PermissionEngine, TeamRecord roles, workspace permissions and HITL middleware. - Identity / ultimate-policy issue: Allowed identity, roles and acceptable operating permissions of configured team members. - Ultimate authority in each claimed mode: No S5-specific autonomous/parent owner established; execution-level rules are narrower than ultimate policy. - Return-to-operation path: Permission decisions guard specific tool calls and inheritance to child agents, not a proven changing-policy feedback loop. - Closure path: Permission request/policy → allow/deny action, lacking ultimate identity-level decision. - Why this is / is not agent-owned: A policy engine enforces rules but does not decide the system&#39;s ultimate purpose or identity. - Evidence: src/agentscope/permission/engine.py; src/agentscope/app/tool/agentcreate.py; src/agentscope/app/service/toolkit.py. - Basis: unknown -\">?</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/44d6c86f16e424c65ea333f05cf07553822f7db5/assessments/agentscope-2-0.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 44d6c86f16e424c65ea333f05cf07553822f7db5\">44d6c86 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-16T22:21:05Z\"><th scope=\"row\"><a href=\"https://github.com/letta-ai/letta\" target=\"_blank\" rel=\"noopener\">Letta</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/letta-ai/letta/tree/5bcdd177d70fa2b31a754cfcd801e77b2e1ab16a\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 5bcdd177d70fa2b31a754cfcd801e77b2e1ab16a\">5bcdd17 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: the primary agent owns model/tool action decisions and can delegate bounded work to first-party subagents.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: subagent launch, parallel execution and lifecycle tracking do not establish an autonomous anti-oscillation/shared-resource coordination decision right among peer S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: the subagent manager schedules/delegates tasks but does not own whole-system current priorities, resources and commitments as a superior regulator.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: the default compaction-triggered reflection path launches a distinct autonomous background reviewer over already-completed primary-agent conversations. It searches for mistakes, contradictions and durable corrections and has an automatic integration path into parent memory/skills. This is a separate complementary audit/correction loop rather than ordinary self-reflection inside the S1 turn.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: reflection is retrospective internal learning from the agent&#39;s own conversations. It does not establish a distinct outside-and-then environmental intelligence function coupled to strategic adaptation.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: reflection may maintain memory/persona/skills, but ultimate identity, policy and authority remain constrained by parent/runtime configuration; editable memory is not legitimate S5 closure.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ae8749aa005ea42801ed86e32476f5c417ecd9a0/assessments/letta.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ae8749aa005ea42801ed86e32476f5c417ecd9a0\">ae8749a &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:24:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/FoundationAgents/MetaGPT\" target=\"_blank\" rel=\"noopener\">MetaGPT</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/FoundationAgents/MetaGPT/tree/11cdf466d042aece04fc6cfd13b28e1a70341b1f\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 11cdf466d042aece04fc6cfd13b28e1a70341b1f\">11cdf46 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: specialized role agents autonomously produce requirements, designs, code, analyses and other operational artifacts.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: the reviewed leader/SOP path primarily assigns and sequences work. No separate evidence shows a function that dampens destructive interference or oscillation among autonomous S1 units without centralizing their decisions.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the default TeamLeader has a whole-team current view through team information, routed feedback and a structured plan; it can regulate current commitments by assigning specialists, closing tasks, changing/resetting the plan and gating downstream work on prerequisite results. This goes beyond worker selection alone and is exercised by an autonomous shipped role. Parent-authored roles, SOPs, prompts, budget and team composition constrain this loop but do not provide a separate first-party human/operator decision path over the same current whole-team commitments, so no (P) mode is published.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: review/testing inside the normal software-production path does not provide a materially independent alternative access channel to operational reality.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: planning, product/competitive artifacts and replanning are project work; the reviewed runtime does not establish a distinct external-and-prospective adaptation loop in two-way conversation with S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: role definitions, SOP, prompts, budget and team composition are parent/developer authored. No runtime agent holds legitimate ultimate identity/policy closure for the system-in-focus.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9ee1ea7472777767928c8b2ab035e0948a0467e9/assessments/metagpt.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9ee1ea7472777767928c8b2ab035e0948a0467e9\">9ee1ea7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-09-18T23:12:56+03:00\"><th scope=\"row\"><a href=\"https://github.com/lobehub/lobehub\" target=\"_blank\" rel=\"noopener\">LobeHub</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-18\">2026-09-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/lobehub/lobehub/tree/3af256caae11796da471bec5f57d882853f30f19\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3af256caae11796da471bec5f57d882853f30f19\">3af256c &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: specialized agents autonomously perform assigned conversational, research, creation or tool-using work. - Disturbance / variety regulated: open-ended user tasks, domain-specific information, tool/model observations and task-specific uncertainty. - Decisive decision or feedback right: choose the substantive actions and output needed for the agent&#39;s assigned task or conversational role. - Decision owner: the invoked model-driven agent. - Supporting / enforcement mechanisms: agent configuration, system role, model/provider selection, plugins, isolated async task context and session state. - Closure path: agent receives an instruction, performs work, returns a result to the group/user, and that result becomes input to subsequent orchestration or conversation. - Why this is / is not agent-owned: the model-driven agent owns substantive task execution while LobeHub transports context/tools/results. - Evidence: README.md, docs/usage/agent/agent-team.mdx, agent-management manifest/system role. - Basis: explicit + structural -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: coordinate multiple specialized S1 agents by choosing dependent versus parallel work, agent selection, handoff order and group interaction mode. - Disturbance / variety regulated: dependency-sensitive work that would be wrong in parallel, redundant/overlapping contributions, poor handoffs and unstructured multi-agent interaction. - Decisive decision or feedback right: choose whether to use one agent, broadcast, sequential speaking, one async task or multiple parallel tasks, and choose the participating agents/instructions. - Decision owner: the model-driven Group Supervisor / Orchestrator. - Supporting / enforcement mechanisms: speak, broadcast, executeAgentTask, executeAgentTasks, group orchestration runtime, shared group context and supervisor resume after member completion. - Closure path: supervisor analyzes the request, selects a coordination pattern and dispatches agents; member results return to the supervisor, which synthesizes, follows up or changes the next interaction. - Why this is / is not agent-owned: deterministic runtime executes the selected pattern, but the supervisor model owns the coordination discretion over mode, agent selection and follow-up. - Evidence: packages/builtin-tool-group-management/src/systemRole.ts, docs/usage/agent/agent-team.mdx, group orchestration runtime. - Basis: explicit + structural - Confidence: high - Caveats: generic callAgent alone would not establish S2; the positive mapping depends on the explicit dependency/parallelism decision framework and returned supervisor loop. - Distinct S1 units: two or more specialized agents in an Agent Group, each capable of separate operational work. - Inter-S1 disturbance: dependent subtasks can be run in the wrong order, overlapping agents can add redundant work, and independent subtasks can be unnecessarily serialized; first-party guidance also calls out weak handoffs and overlapping roles as collaboration failures. - Attenuating coordination relation: the Group Supervisor chooses sequential, parallel, broadcast or focused modes and assigns work to agents according to dependency and expertise. - Feedback into subsequent S1 behaviour: member outputs resume the supervisor; it can ask follow-ups, synthesize, invoke another agent or terminate the group turn, thereby changing later contributions. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: first-party supervisor policy explicitly diagnoses dependence/parallelizability and selects an attenuation pattern for interactions among distinct operational agents, with returned member results driving further coordination.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no separate whole-group current-control function over resources, commitments, priorities or constraints is established beyond the S2 orchestration itself. - Disturbance / variety regulated: group task routing, model choice and current conversation state were inspected, but no distinct S3 current-control loop is established. - Decisive decision or feedback right: no material first-party owner was found with a whole-system current view and separate authority over group-wide commitments/resources/accountability. - Decision owner: none established for qualifying S3. - Supporting / enforcement mechanisms: agent management, group profile editing, async task execution, scheduling and supervisor orchestration. - Closure path: no qualifying distinct S3 loop was found. - Why this is / is not agent-owned: the orchestrator&#39;s evidenced rights are inter-agent task/mode coordination for the current group operation; naming it supervisor/operator is not enough to promote that same function to S3. - Evidence: group-management system role, Agent Group docs, agent-management tools. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: review another agent&#39;s produced work through a distinct reviewer/editor role and return critique into revision/re-review. - Disturbance / variety regulated: incomplete, unclear, inconsistent or low-quality outputs that require a second perspective before acceptance. - Decisive decision or feedback right: judge produced work, issue feedback and require/refine another contribution. - Decision owner: constructor path; LobeHub supplies explicit iterative/reviewer group patterns, but the developer/user must compose the reviewer role, independence and authority in the concrete group. - Supporting / enforcement mechanisms: iterative Agent Group mode, distinct agent identities, sequential handoffs, shared context and supervisor-mediated repeated turns. - Closure path: producer emits work; reviewer/editor returns critique; producer revises; reviewer can perform final review in the documented iterative pattern. - Why this is / is not agent-owned: a separate model-driven reviewer can own the judgment once composed, but the standard distribution does not assign an invariant independent reviewer or audit authority automatically. - Evidence: docs/usage/agent/agent-team.mdx, packages/builtin-tool-group-management/src/systemRole.ts. - Basis: explicit - Confidence: medium - Caveats: ordinary debate or synthesis is not counted as S3; the positive constructor claim is limited to the explicitly documented review/refine pattern with distinct roles. - Claim being audited: that another agent&#39;s draft/output is sufficiently correct, clear or complete for the group&#39;s purpose. - Ordinary reporting path: producer agent returns its draft/result through the normal group turn. - Complementary access path: a separately configured Editor/reviewer/QA agent receives the produced work and can critique it in an iterative group workflow. - Independence boundary: first-party group mechanics preserve distinct agent identities, but organizational independence/authority of the reviewer is supplied by the group composition rather than guaranteed by runtime policy. - Who acts on findings: the producing agent receives reviewer feedback and revises; the group/supervisor can route the revised result back for final review.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no separate external/prospective organizational intelligence loop is established at the Agent Group boundary. - Disturbance / variety regulated: user preference/history changes are learned, but no distinct future/environment adaptation function is closed. - Decisive decision or feedback right: no material first-party owner was found that senses external/future distinctions, generates adaptation options and returns a selected change into group capability/S3. - Decision owner: none established for qualifying S4. - Supporting / enforcement mechanisms: Personal Memory, editable structured memory, continual learning and tool/search capability. - Closure path: memory changes later agent context directly; no separate outside-and-then option-development loop is established. - Why this is / is not agent-owned: personalization/learning and external tools do not automatically establish S4. - Evidence: README.md, Agent Group/runtime docs. - Basis: explicit + structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no identity/ultimate-policy governance function is established for the Agent Group. - Disturbance / variety regulated: group prompt, member roster and agent configuration can change, but no ultimate identity dispute/authority loop is evidenced. - Decisive decision or feedback right: no material first-party identity-level authoritative decision with a return-to-operation closure was found. - Decision owner: none established for qualifying S5. - Supporting / enforcement mechanisms: group profile, Agent Builder, agent CRUD, prompts, skills and user configuration. - Closure path: configuration edits alter operation, but they are not an evidenced S5 identity/ultimate-policy process. - Why this is / is not agent-owned: prompts and editable configuration are implementation/control artifacts, not proof of VSM S5. - Evidence: docs/usage/agent/agent-team.mdx, agent-management manifest/system role. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9f83e41179680c24cbe23a5091abda11fcc221d0/assessments/lobehub.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9f83e41179680c24cbe23a5091abda11fcc221d0\">9f83e41 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-10-12T16:19:31+03:00\"><th scope=\"row\"><a href=\"https://github.com/kyegomez/swarms\" target=\"_blank\" rel=\"noopener\">Swarms</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-12\">2026-10-12</time></td><td class=\"review-ref\"><a href=\"https://github.com/kyegomez/swarms/tree/3009364a7e44dc3e55fec238b56b3a4fa6949a05\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3009364a7e44dc3e55fec238b56b3a4fa6949a05\">3009364 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Model-directed individual first-party Agent solves a task via model/tool choice, observation and iterative continuation. - Disturbance / variety regulated: Dynamic goals, changing tool outcomes, external model output, context and task errors. - Decisive decision or feedback right: Choose steps, call tools/subagents and decide when to continue or finish an operating task. - Decision owner: Per-agent hosted LLM/Agent runtime, not merely an agent-shaped tuple invoked by a deterministic sequencer. - Supporting / enforcement mechanisms: Agent run, runautonomousloop, tool executor, model wrapper and workspace. - Closure path: Task → model-generated action/tool use → environment result → next model reasoning and eventual completion. - Boundary reachability: Python Agent.run and optional autonomous-loop configuration are used from the published distribution (README.md; swarms/structs/agent.py). - Why this is / is not agent-owned: Context-sensitive model actions select operating acts; loop counters and provider wrappers do not own that choice. - Evidence: swarms/structs/agent.py; README.md. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: In bounded GroupChat mode, mediate multiple model-agent bids competing for a single shared conversational speaking slot, preventing speaker domination while retaining useful contributions. - Distinct S1 units: A configured GroupChat.agents set of independently invoked Agent objects, each producing a context-contingent (score, reply) via model-backed respond tool. - Inter-S1 disturbance: Several operating agents seek the same shared conversation floor simultaneously; unchecked publication produces competing turns, and repeated high-frequency speakers dominate the shared information channel. - Attenuating coordination relation: collectbids calls each agent, selectspeaker applies a shared threshold and recency penalty, chooses exactly one speaker, and post updates common conversation history seen by all peers on the next turn. - Feedback into subsequent S1 behaviour: The selected speaker&#39;s contribution, not all conflicting bids, enters shared history for every agent&#39;s following model turn; recent speakers are penalized in future selections. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: The explicit gate is driven by simultaneous claims to a scarce common conversational medium and recurring dominance, with a fairness attenuation policy and returned altered information environment. - Disturbance / variety regulated: Conflicting simultaneous bids, message crowding and disproportionate conversational control. - Decisive decision or feedback right: Select exactly one admissible turn among competing agent contributions. - Decision owner: First-party deterministic GroupChat floor arbiter, therefore C, not a separate agentic S2 decision owner. - Supporting / enforcement mechanisms: respond(score,message) tool, threshold, recency window/penalty, chosen-speaker posting and shared Conversation. - Closure path: Independently formed bids → contention/fairness gate → one allowed published contribution → next turn&#39;s changed conversation and adjusted future bids. - Boundary reachability: GroupChat.run uses the packaged bidding, selecting and posting operations; this is an opt-in published architecture, not an inactive helper (swarms/structs/groupchat.py; README.md). - Why this is / is not agent-owned: Agents determine proposed content and scores; the decisive inter-agent floor grant is deterministic host policy (C). - Evidence: swarms/structs/groupchat.py; swarms/structs/conversation.py; README.md. - Basis: structural - Confidence: medium - Caveats: Applies to GroupChat&#39;s shared conversation medium, not arbitrary shared file changes or all Swarms topologies. Does not claim broad resource conflict arbitration.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: Model-led HierarchicalSwarm director assigns present worker orders and adjusts ongoing team work from collected subordinate results. - Disturbance / variety regulated: Divergent worker progress/results, uncertain task division, errors and changing completion quality. - Decisive decision or feedback right: Produce a model-derived order batch, choose which specialist performs what, inspect returned outputs and issue fresh orders in further loops. - Decision owner: First-party configured model director; deterministic parseorders and executeorders relay its decisions. - Supporting / enforcement mechanisms: HierarchicalSwarm director, OrderBatch parser, worker dispatch and optional feedback director, conversation storage. - Whole-system current view: Director sees the bounded swarm conversation/worker results and prior execution history, not every organization using Swarms. - Current-control decision scope: Current worker allocation, ordering, revisions and reattempts for the HierarchicalSwarm instance. - Closure path: Director plans and orders → specialized workers run → results return and enter conversation → director next loop reassigns/replans. - Boundary reachability: HierarchicalSwarm.run calls step, rundirector, parseorders, executeorders, and loops over result feedback when maxloops allows (swarms/structs/hiearchicalswarm.py). - Why this is / is not agent-owned: Actual work orders originate in a model-led director within the shipped topology; loop counters and dispatcher enforce, not replace, task choices. - Evidence: swarms/structs/hiearchicalswarm.py; README.md. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S3* / direct audit: - State: ? - Function: Some prebuilt modes include judge/verification or consensus phases; materially independent operating evidence inspection and correction path remains unresolved. - Disturbance / variety regulated: Invalid subordinate claims, low-quality task completion or conflicting agent assertions. - Decisive decision or feedback right: Judge can evaluate outputs; whether it has independent primary-source evidence and authority over correction is not guaranteed. - Decision owner: Configured judge/consensus agent, not established as a truly separately observing auditor. - Supporting / enforcement mechanisms: Hierarchical judge toggle, MajorityVoting consensus and HeavySwarm verification-oriented roles. - Claim being audited: Specialist worker answer/output claims. - Ordinary reporting path: Worker results added to director conversation, majority-voting conversation or final report. - Complementary access path: Shipped judging paths chiefly pass worker outputs/derived conversation text; a separate direct observation of work artifacts has not been established at the first-party boundary. - Independence boundary: A different model/persona is not a guaranteed independent observations channel. - Who acts on findings: Directors or consensus can summarize and reconsider, but an independent audit finding → corrective operational reroute is unproven. - Closure path: Output → judge/consensus verdict → report or next loop, insufficient to classify a distinct S3 audit under the governing method. - Why this is / is not agent-owned: Another LLM rating peer output is not equivalent to a complementary function sampling reality independently. - Evidence: swarms/structs/hiearchicalswarm.py; swarms/structs/majorityvoting.py; swarms/structs/heavyswarm.py. - Basis: unknown -\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S4 / adaptation: - State: ? - Function: Planning prompts, persistent workspace and memory may help later tasks but a decision owner adapting future systemic capability from external prospective observations has not been established. - Disturbance / variety regulated: Future requirements, market or environment shifts and changing task complexity. - Decisive decision or feedback right: Unresolved among user-supplied swarm config, model director and persisted task memory. - Decision owner: No uniquely identified first-party outside-and-then intelligence controller at the bounded swarm recursion. - Supporting / enforcement mechanisms: Conversation/workspace storage, planning role prompts, dynamic agent layouts. - External distinction: Outside facts can enter model context, but information access alone is not S4. - Future / prospective distinction: Multi-loop plans address current task commitments, not shown to adapt future organization capability. - Adaptation option generated: No verified capability-evolution choice produced by a distinct owner. - Path back into current capability / S3: Persistence and plan prompts can affect later runs, but external foresight → applied organizational redesign remains unresolved. - Closure path: Retained context → later work, incomplete future-intelligence and capability-change loop. - Why this is / is not agent-owned: Prompted planning and memory are not enough for S4. - Evidence: swarms/structs/hiearchicalswarm.py; swarms/utils/workspacemanager.py; swarms/structs/agent.py. - Basis: unknown -\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S5 / identity: - State: ? - Function: Configured swarm identity, roles and execution limits exist but an ultimate organizational purpose/policy closure is not traced. - Disturbance / variety regulated: User boundaries, acceptable agent/tool behavior and system-level authority. - Decisive decision or feedback right: Developer/user chooses prompts, members and parameters; no proven ultimate-policy choice by a qualified first-party actor. - Decision owner: User-supplied configuration for role identity and deterministic safety checks; a complete parent policy mode remains unresolved. - Supporting / enforcement mechanisms: system prompts, task role configuration and tool/platform restrictions. - Identity / ultimate-policy issue: Who chooses and revises the organization&#39;s overarching identity, purpose and final authority. - Ultimate authority in each claimed mode: Not established beyond out-of-band user/developer configuration. - Return-to-operation path: Prompt and parameter selection guides run behavior, but no complete governing policy feedback is proven. - Closure path: Configured goals/roles → worker execution; no verified policy challenge/ultimate revision returned to operations. - Why this is / is not agent-owned: A system prompt or fixed role roster is not itself an ultimate decision loop. - Evidence: swarms/structs/hiearchicalswarm.py; swarms/structs/groupchat.py; swarms/structs/agent.py. - Basis: unknown -\">?</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/5b1d5a9c5a355aedd4320e3898fd3b2af3f52800/assessments/swarms.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 5b1d5a9c5a355aedd4320e3898fd3b2af3f52800\">5b1d5a9 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-09-17T21:31:18+03:00\"><th scope=\"row\"><a href=\"https://github.com/camel-ai/camel\" target=\"_blank\" rel=\"noopener\">CAMEL Workforce</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/camel-ai/camel/tree/8c791b7b9cf7deab56cb5a92818c34499af9097f\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 8c791b7b9cf7deab56cb5a92818c34499af9097f\">8c791b7 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: A. Worker agents autonomously execute assigned task work through model/tool loops.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: C. Workforce maintains explicit cross-task dependency state and gates release/order of work across multiple workers. This prevents dependent S1 work from proceeding against unsatisfied predecessor commitments, establishing a concrete coordination path beyond routing. The mechanism is supplied deterministically by Workforce while the application supplies the task graph, so ownership is constructor-side rather than agent-owned.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: A. The Coordinator operates over shared workforce state, assigns work based on worker capability, tracks current commitments, handles failures, and can create new workers or redirect/replan work. These are whole-workforce current-control rights over assignments and available operational capacity. The model-driven coordinator owns the runtime choice within configured bounds.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: —. Quality/failure analysis evaluates returned task results in the ordinary Workforce control/reporting path. No materially complementary evidence-access channel or protected independent audit boundary was established. The historical C therefore does not survive current S3 criteria.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: —. Replanning and dynamic worker creation respond to current-task failure; they do not establish an external/future environmental intelligence loop that changes organizational capability.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: —. Human pause/stop/skip controls and the externally supplied objective are parent/operator controls over ordinary execution, not a demonstrated ultimate-policy/identity closure path. The historical P is therefore removed.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/cfe27303e117e1fd3a79fc8f485f33caada591a4/assessments/camel-workforce.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit cfe27303e117e1fd3a79fc8f485f33caada591a4\">cfe2730 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-09-19T19:14:57+03:00\"><th scope=\"row\"><a href=\"https://github.com/micro/go-micro\" target=\"_blank\" rel=\"noopener\">Go Micro</a><small>2015</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-19\">2026-09-19</time></td><td class=\"review-ref\"><a href=\"https://github.com/micro/go-micro/tree/792b18c3010715e2f12621f0120bf058be225482\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 792b18c3010715e2f12621f0120bf058be225482\">792b18c &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously transform user/task state through a model → tool/service/delegation → observation loop until an operational result is produced. - Disturbance / variety regulated: heterogeneous user goals, changing service/tool availability, tool/RPC/A2A results, persistent conversation state, provider responses, tool failures and intermediate observations requiring context-sensitive next actions. - Decisive decision or feedback right: choose the next service/custom/built-in tool, decide whether to plan or delegate, consume returned observations, continue the loop or settle the answer. - Decision owner: the active Go Micro LLM agent in NewAgent or micro chat direct-service mode. - Supporting / enforcement mechanisms: model adapters, service registry/tool discovery, built-in plan/delegate/request-input tools, memory/store, tool wrappers, step/loop/spend limits, approvals, checkpointing, retry/timeout logic, RPC/A2A/MCP integration. - Closure path: user/assigned task + current context → agent selects action/tool/delegation → Go Micro executes/gates it → tool/service/sub-agent result returns into model context → agent selects another action or final result. - Boundary reachability: NewAgent and micro chat are shipped, documented first-party runtime modes; the positive S1 loop is implemented in agent/ and CLI runtime code rather than inferred from examples or repository dogfood. - Why this is / is not agent-owned: removing the model-driven agent while retaining registry, memory, tool execution and guardrails leaves no contextual actor choosing the next operational action. Deterministic wrappers constrain and transport the model&#39;s decisions rather than replacing them. - Evidence: README.md, agent/builtin.go, cmd/micro/chat/chat.go. - Basis: structural - Confidence: high - Caveats: external model inference and remote A2A peers are substrate/environment. The positive state is established independently by the first-party agent loop around those dependencies.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2-specific loop was established that regulates a concrete interference/conflict/oscillation among distinct Go Micro S1 agent units at the declared product-runtime recursion. - Disturbance / variety regulated: candidate paths inspected included multiple registered agents, RPC/A2A handoffs, service discovery/load balancing, durable flows, duplicate delegate/retry protection and shared registry/store infrastructure. - Decisive decision or feedback right: no qualifying S2-specific decision right is supplied. Delegation selects another actor for a subtask; service discovery/load balancing routes calls; idempotency/retry controls duplicate side effects; flow edges order work. - Decision owner: none established for S2 in the reviewed standard product-runtime boundary. - Supporting / enforcement mechanisms: registry, client load balancing, broker/store, plan/delegate tools, A2A/MCP transport, flow sequencing, retry/idempotency guards and isolated ephemeral sub-agent context. - Closure path: no first-party path was found that detects a specific interaction disturbance among two distinct S1 agents, selects an attenuation response for that disturbance, and feeds the coordination result back into subsequent local S1 behaviour. - Why this is / is not agent-owned: multi-agent reachability, routing and delegation are present, but the Methodology explicitly requires more than communication/handoff. The reviewed product runtime does not supply an S2-specific autonomous or constructor path tied to a concrete inter-S1 oscillation/conflict witness. - Evidence: README.md, agent/builtin.go, gateway/a2a/a2a.go. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct first-party whole-system current-control function was established beyond local agent planning/delegation and deterministic runtime enforcement. - Disturbance / variety regulated: candidate current-control paths inspected included store-backed plans, delegation, flow execution state, registry discovery, tool approvals, spend/step/loop limits and runtime stop/resume mechanisms. - Decisive decision or feedback right: the ordinary agent may revise its own task plan and delegate subtasks, but no separate product-runtime path was found with a whole-system current view plus authority to bargain/regulate shared resources, commitments or priorities on behalf of multiple operational units. - Decision owner: none established for S3 at the declared recursion. - Supporting / enforcement mechanisms: plan memory, delegate routing, flow state/checkpoints, registry/client machinery, tool/step/loop/spend limits, approvals and cancellation/timeouts. - Closure path: no S3-specific whole-system feedback/intervention loop was established. Local plan updates return to the same agent&#39;s task execution; deterministic limits enforce preselected constraints. - Why this is / is not agent-owned: a parent agent that decomposes one user request and delegates one subtask is not automatically S3. The reviewed evidence does not show a standard mode where an agent receives a whole-system operational view and owns ongoing resource/commitment intervention across independent S1s. - Evidence: agent/builtin.go, README.md, flow/. - Basis: structural - Confidence: high - Caveats: .github/loop has project-level planning/current-work behavior, but it belongs to the excluded repository-development organization and is not borrowed into the product-runtime S3 mapping.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: challenge a flow-step result through a distinct verification judgment and return rejection feedback into another operational attempt before the flow proceeds with the bounded result. - Disturbance / variety regulated: plausible but deficient step outputs that ordinary body execution would otherwise return without a separate grade-and-correction pass. - Decisive decision or feedback right: the Grader decides pass/fail and supplies corrective feedback; Verify threads rejection feedback into the next body attempt and records the final verification outcome. - Decision owner: Go Micro does not ship a sufficiently independent default autonomous auditor for the general case. LLMGrader reuses the flow model and only sees the latest result. The application must compose a grader with independence appropriate to the audited claim; Go Micro supplies the S3-specific verification/feedback closure. - Supporting / enforcement mechanisms: bounded Verify attempt loop, feedback-field injection, optional backoff, verification metadata, flow checkpoint/result state and optional LLMGrader helper. - Closure path: body produces candidate result → composed grader audits it → rejection/feedback enters the next body input → body retries → accepted or bounded-failure result becomes the flow state. - Claim being audited: whether the current flow-step output satisfies the deployment-defined rubric/ground truth before it is accepted as the step&#39;s result. - Ordinary reporting path: the body step returns its State as normal flow output. - Complementary access path: the first-party Grader seam invokes a separately composed grading actor after body completion; the deployment can give that actor external ground truth, raw artifacts or a distinct model/service, and Go Micro closes its verdict back into retry. - Independence boundary: independence is not guaranteed by the built-in LLMGrader; it is intentionally left to the developer-supplied Grader. This is why the state is C, not A. - Who acts on findings: flow.Verify deterministically reinjects grader feedback into the next body attempt; the operational body/agent then produces the corrected candidate. - Boundary reachability: flow.Verify, the Grader contract and feedback/retry closure are shipped public first-party flow primitives at the reviewed revision, not CI-only tests. A deployment only needs to supply the independent grading actor/ground-truth access. - Why this is / is not agent-owned: the function-specific audit path and return loop are first-party, but the decisive sufficiently independent audit actor is not supplied in a standard autonomous mode. General custom-code extensibility is not the basis; the credit is for the dedicated Verify/Grader primitive whose semantics are verification judgment plus corrective return. - Evidence: flow/verify.go, flow/verifytest.go. - Basis: explicit - Confidence: medium-high - Caveats: same-model LLMGrader alone is not treated as sufficient complementary independence. A deployment that wires only that helper may not operationally realize S3 even though the first-party constructor exists.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A(P) - Function: detect that current operational capability cannot satisfy an external requirement, develop a service-level adaptation, materialize it, and return the new capability into subsequent agent operation. - Disturbance / variety regulated: new user needs not covered by existing registered services/tools; requests to extend or modify an existing system; design/code/compile failures encountered while materializing the capability. - Decisive decision or feedback right: Base mode — the micro chat agent decides that no existing service can handle the request and chooses microgenerateservice; the generation models choose the service architecture/handler changes. Parent mode — the user reviews the LLM-designed system proposal and decides at Generate? [Y/n] whether the adaptation should be materialized. - Decision owner: Base mode — the autonomous chat/generation model path. Parent mode — the human operator owns the decisive accept/reject adaptation judgment, while the generator autonomously develops and implements the approved option. - Supporting / enforcement mechanisms: registry/tool discovery, generate.Design, existing-service scan, deterministic service-structure generation, LLM handler generation, bounded compile-fix loop, process startup, registry wait and tool refresh. - Closure path: external capability request + current service inventory → missing-capability distinction → model designs service adaptation → autonomous choice or parent approval triggers generation → code is written/compile-fixed/built/started → registry/tool set refreshes → subsequent agent turns can use the new service. - External distinction: the user asks for a capability absent from the current registered service/tool environment, or asks to extend/modify the existing system. - Future / prospective distinction: Go Micro models a desired future system/service capability relative to the current inventory rather than only selecting among existing tools; Design explicitly receives existing services and constructs the complete extended target design. - Adaptation option generated: one or more new/modified Go Micro services with schema/endpoints, generated handler/business logic and an updated managing agent/tool surface. - Path back into current capability / S3: generated services are compiled and started, allowed to register, micro chat refreshes discovered tools, and the new endpoints become immediately usable by the same operational agent; in initial generation mode the approved system becomes the subsequent running service/agent environment. - Boundary reachability: both micro chat autonomous missing-capability generation and micro run --prompt / CLI user-approved generation are shipped documented CLI modes. The positive mapping does not depend on repository CI or .github/loop dogfood. - Why this is / is not agent-owned: in base mode removing the model&#39;s missing-capability judgment/service-design choices leaves only a generator with no contextual adaptation decision. In parent mode the human decides whether the proposed adaptation is admitted, and that decision is returned through the same generator into executable capability. - Evidence: cmd/micro/chat/chat.go, cmd/micro/cli/generate/generate.go, cmd/micro/run/run.go, README.md, flow/analyze.go. - Basis: explicit - Confidence: high - Caveats: the adaptation path is developer/runtime oriented rather than production hot-patching of an arbitrary deployed service; the credited mode is nevertheless first-party and explicitly returns generated service capability into the supported running micro chat environment. flow.Analyze/LLMOptimizer alone would be only a partial adaptation constructor because applying its prompt proposal is caller-owned.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no product-runtime identity/ultimate-policy decision loop was established at the declared recursion. - Disturbance / variety regulated: candidate paths inspected included agent system prompts, auth/rules, tool approvals, spend/step/loop limits, requestinput, generated-service confirmation and repository North Star/maintainer restrictions. - Decisive decision or feedback right: none of the product-runtime mechanisms escalates a genuine identity/ultimate-policy issue to a legitimate ultimate authority and returns that decision to govern subsequent operation at this recursion. - Decision owner: none established for S5 in the assessed product runtime. - Supporting / enforcement mechanisms: auth rules/JWT wrappers, guardrails, tool approvals, static prompts/configuration, human input pauses, spend budgets and generation confirmation. - Closure path: ordinary task/action approvals and configuration changes can alter execution, but no identity/ultimate-policy issue → legitimate authority → authoritative decision → returned policy loop was found. - Why this is / is not agent-owned: policy text, permission checks and human approvals bound ordinary operations; they do not by themselves own system identity or ultimate policy. Repository NORTHSTAR and off-limits maintainer decisions belong to the excluded repository-development organization. - Evidence: agent/builtin.go, auth/, internal/docs/CONTINUOUSIMPROVEMENT.md. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9a9faa2e1208ecb2712c492398de7b7e7f24976a/assessments/go-micro.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9a9faa2e1208ecb2712c492398de7b7e7f24976a\">9a9faa2 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-11-11T18:07:26+03:00\"><th scope=\"row\"><a href=\"https://github.com/milletcode/milletcode\" target=\"_blank\" rel=\"noopener\">MilletCode</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-11\">2026-11-11</time></td><td class=\"review-ref\"><a href=\"https://github.com/milletcode/milletcode/tree/2278a648381e3279bb1f29ed54cf48ad19c44d66\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 2278a648381e3279bb1f29ed54cf48ad19c44d66\">2278a64 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: carry out model-directed coding/dialog tasks in configured project workspaces. - Disturbance / variety regulated: changing prompts, code/tool observations, permissions, session context and test results. - Decisive decision or feedback right: the Claude Code model chooses next edits, tools and responses during a live session; users may approve/deny restricted actions. - Decision owner: first-party-launched Claude Code agent process in an enabled instance, whose model reasoning is external but whose session/approval/feedback organization is shipped by MilletCode. - Supporting / enforcement mechanisms: ClaudeAdapter process launcher, SessionManager, JSONL event parser, approval response handling, SSH/local runtime and WebSocket streaming. - Closure path: browser/API prompt → launched Claude CLI with project context → model/tool work → streamed event or approval → user/CLI response → continued model step or completed session. - Boundary reachability: Claude adapter is enabled by default and SessionManager::createsession resolves its configured local or SSH executable; no custom third-party framework implementation is needed beyond installing Claude Code. - Why this is / is not agent-owned: model selects content/steps and handles tool feedback; backend only starts, meters, routes and persists the session. - Evidence: Claude adapter launch/events, session management, session API. - Basis: structural shipped CLI agent mode. - Confidence: high for adapter-agent reachability, not for quality of model execution. - Caveats: no model-provider credentials or live end-to-end workflow tested; HTTP agent adapters are immature/disabled and not needed for the S1 claim.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no evidenced first-party discretionary regulation of interfering decisions among distinct running coding agents. - Disturbance / variety regulated: two agents could touch the same source files or make incompatible changes, but no inter-agent collision resolution loop is shipped. - Decisive decision or feedback right: per-session duplicate-key overwrite/resume and resource handling decide session identity, not cross-agent work-claim arbitration. - Decision owner: absent for an S2-specific corrective choice; operators manually coordinate tasks outside this provided relation. - Supporting / enforcement mechanisms: composite session keys, status registry, SSH pooling, approval queue, task-specific stop/resume and notifications. - Closure path: no first-party scope conflict event → coordination verdict → changed instructions to two distinct S1 agents demonstrated. - Why this is / is not agent-owned: session identity deduplication and transport routing prevent duplicate sessions but do not attenuate conflicting independent tasks across agents. - Evidence: session manager, session API, multi-agent feature description. - Basis: bounded no-path within included session/agent/transport and project surfaces. - Confidence: medium-high. - Caveats: an operator or external Claude agent could independently coordinate work; that is not the first-party default S2 loop.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: oversee and intervene in currently active sessions and project commitments across the operator&#39;s MilletCode installation. - Disturbance / variety regulated: stuck/idle agents, unexpected approvals, errored sessions and competing current project work. - Decisive decision or feedback right: human operator can select projects/sessions, issue work messages, stop/resume instances, resolve pending approvals and change active execution configuration. - Decision owner: authenticated local/hosted human console operator; no model is shown prioritizing all sessions from a whole-deployment view. - Supporting / enforcement mechanisms: dashboard and sessions routes, persistent session store, SessionManager, status APIs, pending-control registry, idle alerts and project discovery. - Whole-system current view: /api/sessions and projects console enumerate running/idle/stopped sessions across projects and agents, with current status and approval prompts. - Current-control decision scope: operator allocates attention and instructions, intervenes in stuck sessions and changes which active coding threads continue. - Closure path: aggregated session/project state → operator selects intervention/priority → REST action (message/approve/stop/restore) → changed agent process and subsequent dashboard state. - Boundary reachability: installed browser dashboard and REST session controls are first-party supported modes, not maintainer-only developer infrastructure. - Why this is / is not agent-owned: whole-session decisions require human selection; automatic status updates and Lark notifications only report/enforce. - Evidence: sessions API, session manager, console. - Basis: direct parent-operated current-control path. - Confidence: medium-high for parent supervision; actual scheduling effectiveness untested. - Caveats: current S3 belongs to the deployed operator, not an autonomous model supervisor; a session&#39;s approval prompt alone would not prove S3 without the whole view.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no independent first-party review of coding-agent operational claims with separate evidence access and a corrective verdict demonstrated. - Disturbance / variety regulated: coding errors/false completion reports remain possible; installation validation and permission checks address different narrower hazards. - Decisive decision or feedback right: no shipped independent code-audit actor/constructor returns a judgment that changes worker behavior. - Decision owner: human may inspect artifacts externally, but that reviewer is not a first-party complementary path in this installed system. - Supporting / enforcement mechanisms: session history, Git/file browser, per-action approvals and skill after-install checks. - Closure path: user can view output and decide manually; an independent audit → findings → corrective agent control loop is not supplied. - Why this is / is not agent-owned: approval prompts are permission decisions, and existence checks for installed skills do not review agent code/work independently. - Evidence: sessions UI/API, skills verification, README. - Basis: bounded absence of independent S3 audit boundary. - Confidence: medium-high for standard distribution. - Caveats: external CI or a separately hired model reviewer could be attached, but is not credited without a first-party integration.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S4 / adaptation: - State: P - Function: select external skill packages as future coding-agent capability options and deploy the chosen adaptation across configured agent nodes. - Disturbance / variety regulated: new external skill capabilities and changing local agent requirements beyond a current user prompt. - Decisive decision or feedback right: a human operator evaluates the available official/third-party skill option and requests install/uninstall; no autonomous model has blanket authority to define future capabilities. - Decision owner: human console operator who chooses a skill and, for official packages, provides/configures the trusted download source; model-run third-party installers execute that request within bounds. - Supporting / enforcement mechanisms: official skill manifest, skills marketplace UI, API install queues, configured archive source/password, per-node plan, verification after install, persistent status. - External distinction: skill packages originate outside the currently installed agent session and may introduce capabilities it previously lacked, unlike session state, logs or immediate code output. - Future / prospective distinction: the operator selects a reusable capability for subsequent sessions rather than merely answering an ongoing coding turn. - Adaptation option generated: displayed available skill packages plus manually supplied third-party skill requests; choice remains human and the catalog is not independent strategic research. - Path back into current capability / S3: operator skill selection → official/third-party install API → per-agent/node skill directory update and verification → sessions using newly available installed skills. - Closure path: offered outside skill option → parent selection/approval → installation/verification → changed agent skill availability → later coding operations. - Boundary reachability: first-party skills.rs routes and Skills UI are shipped; official install requires an explicitly configured source, while third-party install requires an operator-provided request. - Why this is / is not agent-owned: software/agents may execute installation, but the prospective option and authorization are owned by the operator, so parent P rather than A. - Evidence: skills API and install verification, skill market UI, README feature description. - Basis: first-party parent-governed capability acquisition path, narrow S4. - Confidence: medium; live source availability and installed-skill usefulness not tested. - Caveats: not general environmental foresight, adaptive product strategy or autonomous skill selection; no claim official downloads work without configured URL/password.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no evidenced first-party path where the installed deployment&#39;s ultimate mission/identity is authoritatively selected and returned into operations. - Disturbance / variety regulated: credential/auth and agent allowlists constrain execution, but do not settle the ultimate purpose of the deployment. - Decisive decision or feedback right: operator can configure access, default model, approvals and skills, but no specific ultimate-identity decision circuit is shown. - Decision owner: legitimate human owner retains general authority outside the runtime; operational permissions should not be mislabeled a closed S5 function. - Supporting / enforcement mechanisms: config.toml, auth.mode, agents/instances, approval controls, SSH credentials and skill installation policy. - Closure path: settings change execution permissions and capacity, not an explicit identity-level mission/organizational purpose selection and return. - Why this is / is not agent-owned: no model owns policy identity, and human password/approval controls alone do not establish parent S5 by the function-first threshold. - Evidence: configuration, README configuration, approval API. - Basis: bounded no-path at installed boundary. - Confidence: medium; an operator&#39;s outside organizational identity is not denied. - Caveats: selecting a new skill as future capability is S4 P here, not itself S5 identity authority.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/70a43d08d80314385bda7c8aac6af10e0cdf8810/assessments/mi/milletcode.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 70a43d08d80314385bda7c8aac6af10e0cdf8810\">70a43d0 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-11-11T17:36:00+03:00\"><th scope=\"row\"><a href=\"https://github.com/devsohm/axi\" target=\"_blank\" rel=\"noopener\">Axi</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-11\">2026-11-11</time></td><td class=\"review-ref\"><a href=\"https://github.com/devsohm/axi/tree/b1d0fe007535f1c59d08c1f06e014c4558a4862d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b1d0fe007535f1c59d08c1f06e014c4558a4862d\">b1d0fe0 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Complete a submitted task through model-selected actions and committed feedback. - Disturbance / variety regulated: Tool outcomes, model errors, context limits, interruptions and partially complete work. - Decisive decision or feedback right: Select the next supported tool and its arguments, revise the action after tool observations, or return an answer. - Decision owner: The model bound to the packaged GenerationTask owns semantic choices. The harness owns phase execution and persistence. - Supporting / enforcement mechanisms: Model collection, first-party provider adapters, ToolTask, registered tool factories, scheduler, views and checkpointed storage. - Closure path: Conversation submit → GenerationTask selects request → model calls a tool → ToolTask records result → next generation consumes result or commits completion. - Boundary reachability: Harness.open, root submission, GenerationTask and ToolTask are public supported distribution paths. The shipped provider can be configured in place of the tutorial faux provider. - Why this is / is not agent-owned: The host selects provider and tool policy. The model makes per-task decisions through the supplied standard executor without a host-authored control loop. - Evidence: packages/durable/docs/tutorial.md, packages/durable/src/harness/harness.ts, packages/durable/src/harness/generation.ts, packages/durable/src/harness/generation.ts, packages/durable/src/tools/index.ts, packages/ai/src/api/openai-responses.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No autonomous coordination between distinct S1 units is established. - Disturbance / variety regulated: Parallel conversations and file mutations can share resources. - Decisive decision or feedback right: Resolve inter-conversation interference and change subsequent operating choices across the units. - Decision owner: Scheduler and mutation queue serialize work under fixed rules. The host defines any inter-conversation policy. - Supporting / enforcement mechanisms: Ownership graph, task scheduler, document transactions and canonical-file mutation queue. - Closure path: Locks and task ordering regulate writes and resource access. Results return to the originating tool or conversation. - Boundary reachability: Child conversations, task ownership and file tools are present. - Why this is / is not agent-owned: The implemented lifecycle and write serialization do not expose a distinct cross-S1 decision/feedback role. - Evidence: packages/durable/src/harness/scheduler.ts, packages/durable/src/harness/ownership.ts, packages/durable/src/tools/file-mutation-queue.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No whole-system current-control decision mode is established. - Disturbance / variety regulated: Live tasks, stalled phases, conversation usage and cancellation requests. - Decisive decision or feedback right: Reallocate or change whole-system operating commitments with returned discretionary intervention. - Decision owner: The app chooses configuration. The scheduler manages present phases under fixed lifecycle rules. - Supporting / enforcement mechanisms: Task graph, views, checkpoints, metadata telemetry and cancellation. - Closure path: Current statuses drive scheduling, restart and cancellation within the lifecycle contract. - Boundary reachability: The public Harness exposes task inspection and conversation control primitives. - Why this is / is not agent-owned: Observations and isolated operator controls leave the whole-system judgment and return to adopter code. - Evidence: packages/durable/src/harness/harness.ts, packages/durable/src/harness/scheduler.ts, packages/durable/src/harness/task-graph.ts, packages/durable/src/harness/view.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No complementary operational audit is established. - Disturbance / variety regulated: An agent response or tool outcome may disagree with task reality. - Decisive decision or feedback right: Inspect alternative evidence and return a claim-specific corrective judgment. - Decision owner: Producing conversation receives committed tool results. Hosts own any telemetry or extra hook logic. - Supporting / enforcement mechanisms: Recorded tool phases, transcript, durable telemetry and development test fixtures. - Closure path: Runtime records return to the same conversation or host subscribers. There is no audit verdict in standard generation settlement. - Boundary reachability: Packaged telemetry and task views expose event observations. - Why this is / is not agent-owned: Neither a hook nor a second arbitrary conversation carries audit-specific independence and return by default. - Evidence: packages/durable/src/harness/generation.ts, packages/durable/src/harness/telemetry.ts, packages/durable/src/harness/registry.ts, packages/durable/README.md - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No prospective adaptation loop is established. - Disturbance / variety regulated: Changes in model catalogs, context length or available extensions may affect future tasks. - Decisive decision or feedback right: Sense outside change, judge a future capability option and feed it into present operations. - Decision owner: Host selects model configuration and extensions. Compaction maintains the active conversation context. - Supporting / enforcement mechanisms: Model catalogs, compaction tasks, configuration and persisted context boundaries. - Closure path: The compaction output changes the next prompt. It does not commit a prospective capability adaptation. - Boundary reachability: Compaction is a supported conversation function. Catalog tooling belongs to model package maintenance. - Why this is / is not agent-owned: Selecting or summarizing context for current work does not assign outside-and-then ownership. - Evidence: packages/durable/src/harness/compaction.ts, packages/durable/src/harness/agent.ts, packages/ai/src/model-catalog.ts, packages/durable/docs/spec.md - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No ultimate identity/policy decision process is established. - Disturbance / variety regulated: Host policy, request identity overrides and conversation-level settings. - Decisive decision or feedback right: Resolve an identity-level dispute and apply the authoritative result to future operation. - Decision owner: The embedding application supplies policy and identity fields. Harness applies runtime configuration. - Supporting / enforcement mechanisms: Request identity, extension registry, AgentDoc settings and ownership checks. - Closure path: Configured identity and tool policy influence requests and run admission under predefined rules. - Boundary reachability: Harness.open and conversation configure are supported configuration paths. - Why this is / is not agent-owned: An attribution string, permission boundary or configuration override does not substantiate ultimate authority arbitration. - Evidence: packages/durable/README.md, packages/durable/src/harness/harness.ts, packages/durable/src/harness/agent.ts, packages/durable/src/harness/ownership.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/09960790f90ed113da880c0571998635cbf1927e/assessments/ax/axi.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 09960790f90ed113da880c0571998635cbf1927e\">0996079 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-11-11T17:22:17+03:00\"><th scope=\"row\"><a href=\"https://github.com/Andy1890/ruhui-agent\" target=\"_blank\" rel=\"noopener\">RuHui Agent</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-11\">2026-11-11</time></td><td class=\"review-ref\"><a href=\"https://github.com/Andy1890/ruhui-agent/tree/4bbff9f3094f5024edb7e25ba36b4c31d55df7d6\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 4bbff9f3094f5024edb7e25ba36b4c31d55df7d6\">4bbff9f &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Carry out a local user task through iterative model-selected tool actions. - Disturbance / variety regulated: Tool failures, malformed output, incomplete workspace information and consumption limits. - Decisive decision or feedback right: Choose the next supported tool and its arguments, revise after observations, or finish with text. - Decision owner: The model actor bound to the first-party CLI/SDK turn owns the semantic choices. The runtime owns dispatch and fixed limits. - Supporting / enforcement mechanisms: Provider adapter, context assembly, tool mode policy, local handlers, rollout and budget checks. - Closure path: Task → provider response → tool call → local observation or corrective hint → next provider step → completion or bounded stop. - Boundary reachability: CLI delegates to the SDK and the SDK binds the configured provider and executor before calling the core loop. The OpenAI-compatible adapter is an implemented mode. - Why this is / is not agent-owned: The semantic action is selected from task and results by the model. The scripted provider is a fixture mode and does not substantiate agent ownership by itself. - Evidence: packages/cli/ruhui.mjs, packages/sdk/agent-node.mjs, packages/core/src/loop.ts, packages/providers/openai-node.mjs - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No distinct S1 coordination is established in the local turn boundary. - Disturbance / variety regulated: Tool order and per-workspace state can affect the current task. - Decisive decision or feedback right: An inter-operation conflict judgment would require independently operating S1 units sharing a relevant disturbance. - Decision owner: The active turn owns its tool decisions. The runtime sequences calls and keeps session state. - Supporting / enforcement mechanisms: Serial tool dispatch, tool-batch concurrency flags and local rollout/session boundaries. - Closure path: Tool results return to the same turn. No lateral conflict signal is returned between S1s. - Boundary reachability: The CLI and SDK bind the same single-turn execution path. - Why this is / is not agent-owned: Ordering tools issued by one model is internal to S1. - Evidence: packages/core/src/loop.ts, packages/tools/src/runtime.ts, packages/sdk/agent-node.mjs - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No separate current-control process over whole-system commitments is established. - Disturbance / variety regulated: Current turn cost, time and repeated tool failures. - Decisive decision or feedback right: A portfolio-level intervention would require a current view and discretion over commitments beyond the turn. - Decision owner: The local constructor defines budgets and stopping rules. The user initiates or resumes work. - Supporting / enforcement mechanisms: Consumption counters, failure caps, exit states and the CLI doctor. - Closure path: Counters and observations produce fixed continuation or stopping behavior for the current turn. - Boundary reachability: SDK run/resume and doctor are reachable. Their current scope is local session execution and readiness. - Why this is / is not agent-owned: Local budget guards execute configured rules inside S1. - Evidence: packages/core/src/loop.ts, packages/core/src/budget.ts, packages/sdk/agent-node.mjs - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No complementary operational audit is established. - Disturbance / variety regulated: Potential disagreement between a task claim and actual workspace or tool outcomes. - Decisive decision or feedback right: Independently sample evidence for the claim and return a corrective judgment. - Decision owner: The producing turn receives its own tool results. Development checks are maintained separately from task operation. - Supporting / enforcement mechanisms: Rollout events, deterministic rollout checks and eval fixtures. - Closure path: Runtime feedback goes back to the original model. Offline checks have no first-party return into current task control. - Boundary reachability: The product exposes its own event stream. The evaluation scripts are repository development commands. - Why this is / is not agent-owned: Observation and deterministic checking do not establish a separate claim-specific challenge and return in the shipped operating mode. - Evidence: packages/core/src/loop.ts, packages/sdk/agent-node.mjs, scripts/eval.mjs, scripts/data/rollout.mjs - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No prospective capability adaptation is established. - Disturbance / variety regulated: Workspace context and immediate changes to task inputs. - Decisive decision or feedback right: Observe external change, generate a future option and return it into current capability. - Decision owner: The user chooses workspace instructions and configuration. The active model addresses the current task. - Supporting / enforcement mechanisms: Context discovery, configuration loading and session continuation. - Closure path: The context is assembled for the next local turn without an outside-and-then adaptation path. - Boundary reachability: Workspace and home configuration are loaded in supported modes. - Why this is / is not agent-owned: Task plan updates and context assembly do not govern future capability. - Evidence: packages/core/src/context.ts, packages/sdk/agent-node.mjs, packages/tools/src/plan.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No ultimate identity or policy arbitration process is established. - Disturbance / variety regulated: Local tool permission and instruction constraints. - Decisive decision or feedback right: Resolve a conflict in governing identity or ultimate policy and change operating commitments. - Decision owner: The embedding caller or user configures the runtime, and deterministic tool policy applies the selected mode. - Supporting / enforcement mechanisms: Tool policy, local configuration, user-input result and sandboxed workspace helpers. - Closure path: Configured rules gate the current tool invocation. No first-party identity arbitration precedes those constraints. - Boundary reachability: The first-party dispatcher applies mode policy. The user can respond to task-level requests. - Why this is / is not agent-owned: Per-action permission and external configuration do not constitute a sourced ultimate-policy decision mode. - Evidence: packages/tools/src/policy.ts, packages/tools/src/runtime.ts, packages/sdk/agent-node.mjs, schema/config.schema.json - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/3de8817a771caf386c6598c21360f1d64c98eca8/assessments/ru/ruhui-agent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 3de8817a771caf386c6598c21360f1d64c98eca8\">3de8817 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-11-08T15:35:01+03:00\"><th scope=\"row\"><a href=\"https://github.com/vokramd/markov-harness\" target=\"_blank\" rel=\"noopener\">markov-harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-08\">2026-11-08</time></td><td class=\"review-ref\"><a href=\"https://github.com/vokramd/markov-harness/tree/6ffac34f74e6ee9c1e93cdff145c8d7656a0d769\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 6ffac34f74e6ee9c1e93cdff145c8d7656a0d769\">6ffac34 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: interactive model-selected repository reading, editing, shell execution and bounded specialist delegation in response to user coding requests and tool feedback. - Disturbance / variety regulated: unfamiliar workspace files, command failures, tool denials and evolving coding subtasks within a user session. - Decisive decision or feedback right: the configured LLM chooses substantive tool invocations and next action after reading real results; a child model separately selects its own allowed tools for a bounded delegated task. - Decision owner: main model/agent and, in the supported agent-tool mode, an explicitly invoked specialist model with its own session and tool permissions. - Supporting / enforcement mechanisms: declarative repeat steps, first-party history assembly, read/edit/bash tools, hooks.py gate, optional human approval, rules, container boundary, context compaction and session/memory snapshot. - Closure path: model tool-use blocks enter gate and first-party tool workflows; outputs are recorded as tool-result content in the session; next agentstep call receives updated history and may correct/retry or finish. Child agent.run returns a tool result to main agent. - Boundary reachability: bin/harness invokes Markov with the shipped workflow; normal main -&gt; turn -&gt; agentstep and optional model-produced tools.agent -&gt; agent.run -&gt; subagentstep are implemented, not only illustrated in a test. - Why this is / is not agent-owned: model-dependent choice of tool, arguments and continuation is decisive S1 cognition; predetermined Markov repeat/gates constrain it but do not select individual coding actions. - Evidence: normal turn loop, model/tool feedback, delegated model loop, tool return. - Basis: first-party workflow/source evidence and unit tests; no live model-relay E2E in this assessment. - Confidence: high for the installed S1 model/tool return wiring; not an empirical model-success measurement. - Caveats: a separately installed external Markov engine, Podman and relay credentials are required. The bundled demo and provider claims are not promoted into independent verified operating evidence.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no credited inter-S1 disturbance-specific mutual adjustment with corrective feedback among independent specialists. - Disturbance / variety regulated: possible tool/workspace clashes between separately invoked specialist agents, but no first-party coordination of those clashes is established. - Decisive decision or feedback right: no distinct mediation function shown; the main agent selects delegation and the workflow runs child calls one at a time. - Decision owner: main agent owns task assignment as part of its S1, and deterministic workflow settings own read-only parallelism/mutating serialization; no independent S2 decision owner is evidenced. - Supporting / enforcement mechanisms: runreadonly concurrency 4, runmutating concurrency 1 and sequential runagents, per-tool permission checks and shared worktree. - Closure path: each child completes and reports back to the main model as a tool result; no unresolved conflict representation, peer settlement, reallocation or collision-specific adjustment drives another independent S1 unit. - Why this is / is not agent-owned: generic delegation, deterministic serial execution and permissions may avoid some collisions mechanically but do not establish VSM S2&#39;s interference/attenuation/feedback relation. - Evidence: serialized subagent calls, subagent result flow, README explicitly one-at-a-time. - Basis: source-level workflow modes and supported subagent documentation. - Confidence: high for lack of credited coordination within inspected shipped modes. - Caveats: this does not deny that serial execution is a valuable safety measure; it is not evidence of an independently agent-owned S2 function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no separate whole-harness current control over multiple independently committed S1 cells is established beyond the main agent&#39;s task-level delegation. - Disturbance / variety regulated: tool budget, blocked commands, long transcript, subagent termination and user approvals, all at session-operation level. - Decisive decision or feedback right: main model may call a child tool, while human may approve an individual edit/command; no separate whole-system controller can evaluate current multi-S1 commitments and reallocate them. - Decision owner: main task S1 and deterministic workflow limits, not a demonstrated whole-system S3 actor. - Supporting / enforcement mechanisms: maxtoolrounds, maxturns, approve rules, session continuation and summary compaction. - Closure path: child result folds back into main transcript, tool denial folds into the same agent, and compaction changes that agent&#39;s context; there is no cross-cell S3 resource/commitment closure. - Why this is / is not agent-owned: main-agent operational planning is not automatically promotion to autonomous S3; approval per operation is not parent whole-system control. - Evidence: single-session orchestration, subagent run-and-return, session settings. - Basis: first-party workflow and task/agent mode inspection. - Confidence: medium-high within reviewed distribution. - Caveats: an operator could externally run several instances or coordinate them; such an added organization is not contained in the pinned harness.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no separate independent completed-work reality audit whose finding closes into corrective operational control. - Disturbance / variety regulated: hallucinated file updates or false task completion claims would require independent verification, but reviewed validation paths do not own such audit. - Decisive decision or feedback right: permission gate checks whether a proposed command/edit may run, and PostToolUse hooks may return suggestions; no default reviewer independently measures final claimed deliverables. - Decision owner: user approval and developer-authored hook rules for pre/post tool constraints; neither is an independent auditor of the task&#39;s outcome. - Supporting / enforcement mechanisms: hooks.py, edit diff and validation, tool-result feedback, local script tests, optional model memory extraction. - Closure path: gating sends allow/deny to normal tool execution; memory extraction summarizes conversation history to memory files, not verified real results with independent corrective verdicts. - Why this is / is not agent-owned: pre-execution policy checking and transcript-derived memory are not a distinct reality-reading audit of the completed S1 operation. - Evidence: tool gate and hooks, edit planning, memory extraction workflow. - Basis: code path and self-test review. - Confidence: high for absence of a first-party standalone reviewer within inspected modes. - Caveats: a user might install custom hooks performing validation; an external customized hook is not an established first-party independent audit owner.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no closed first-party external-environment intelligence and prospective organizational adaptation strategy, beyond retrieval/persistence of task memories. - Disturbance / variety regulated: future unfamiliar tasks/user preferences, which the memory files might help with but do not constitute an agent-selected organizational strategy loop. - Decisive decision or feedback right: model may extract memorable preferences/facts from past conversation, but no explicit future environmental option is selected, governed and enacted as a strategic adaptation. - Decision owner: ordinary main task model/optional extraction model for memory text; operator/developer authors permanent workflows, tools and settings. - Supporting / enforcement mechanisms: extract.memories, extract.step, memory.py index and snapshot, user/working-directory instructions, skills lookup and context compaction. - Closure path: extraction stores a fact file and future session prompt may incorporate its index; this is persistent S1 context, not a wider outside-and-then metasystem decision returned into changed organizational capability. - Why this is / is not agent-owned: retained instructions/memories can influence later S1 but have no evidenced externally oriented prospective scanning, alternative selection or strategy implementation closure. - Evidence: memory extraction trigger, extract fork and model pass, persistent memory context. - Basis: workflow and storage/permission paths. - Confidence: medium-high, with the memory mechanism reviewed as plausible false positive. - Caveats: capability to modify arbitrary project files does not by itself establish S4; no change to the first-party configured harness is automatically enacted by extracted facts.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no distinct legitimate ultimate policy/identity decision authority is closed inside the evaluated agent harness. - Disturbance / variety regulated: conflicting system purposes or durable constitution revisions would require a policy-identity adjudicator; source instead installs a fixed identity and user-written instruction precedence. - Decisive decision or feedback right: no model or parent governance agent can authoritatively choose a constitutional identity for the harness; the user edits prompt/config/CLAUDE.md settings outside the agent. - Decision owner: installer/operator and original prompt author define static identity; normal agents select code actions within that envelope. - Supporting / enforcement mechanisms: vars/prompts.yaml static clientidentity/systemprompt, instructions.py snapshots and folder precedence, settings.py permission rules, user approvals. - Closure path: owner-edited instruction/settings text may be loaded in a later session, but no operating first-party identity-level adjudication and authoritative change cycle is established. - Why this is / is not agent-owned: routine permission rules and human approval of one command are operational constraints, not ultimate policy S5; static instructions are necessary identity input but not a decision owner on their own. - Evidence: static prompt variables, instruction snapshot, permission policy. - Basis: source-level prompt/authority and instruction path review. - Confidence: medium-high within first-party runner configuration. - Caveats: parent-maintainer GitHub governance or a user&#39;s own policy choices are outside the installed execution boundary.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/702d486442ef1450bc6c56b4410c04642507a375/assessments/ma/markov-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 702d486442ef1450bc6c56b4410c04642507a375\">702d486 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"3\" data-assessment-at=\"2026-11-08T15:53:17+03:00\"><th scope=\"row\"><a href=\"https://github.com/FuzzyKuji/OpenProgram\" target=\"_blank\" rel=\"noopener\">OpenProgram</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>3</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-08\">2026-11-08</time></td><td class=\"review-ref\"><a href=\"https://github.com/FuzzyKuji/OpenProgram/tree/447264865e871e30e7f638b42cccfe25d826f8d0\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 447264865e871e30e7f638b42cccfe25d826f8d0\">4472648 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: model-directed coding, web/file/shell operations, multi-turn reasoning, and delegated specialist execution with concrete tool-result feedback. - Disturbance / variety regulated: changing user tasks, unknown files and webpages, failed tool actions, incomplete implementation results, and context-dependent follow-up instructions. - Decisive decision or feedback right: an invoked model chooses actual model response/tool calls and how to continue after receiving results; a child/peer model chooses its own assigned work actions inside its own branch. - Decision owner: active configured Agent model for each conversation; user-selected provider is an external implementation dependency. - Supporting / enforcement mechanisms: Agent Python call API, model loop/tool dispatch, tool registry, permission gate, conversation DAG, context assembly, Job/run state, file/edit/shell/web tools and optional worktree context. - Closure path: user or another authorized Agent supplies a task; runtime assembles current context, model requests tool calls, first-party tool dispatch obtains observations/errors, and the next model turn may repair, retry, delegate or conclude. Background child completion returns to the invoking conversation. - Boundary reachability: public openprogram CLI/web entrypoints reach first-party Agent runtime and registered tools; agent tool reaches runagentturn/runagentturnasync; child work is admitted as canonical Job rather than only documented in a scenario. - Why this is / is not agent-owned: tool selection and next-step adaptation are model decisions; deterministic permissions and execution adapters support them without becoming the S1 decision maker. - Evidence: Agent call, tool dispatch, child execution, registered tools. - Basis: shipped executable source, component/unit tests and documented standard invocation; no credentialed live-model E2E. - Confidence: high for first-party tool/model return wiring; provider success rates and operational safety are not measured. - Caveats: account setup, configured model and requested tool permissions are required. Python Agent instance methods are not automatically model tools unless explicitly registered; claims of universally automatic self-programming must not be generalized to every mode.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate capacity interference among separate active Agent conversations/Jobs and give a worktree-using coordinator an explicit integration/conflict feedback surface. - Disturbance / variety regulated: independent child/peer Jobs contending for global/session execution slots, simultaneous claims of the same queued work, and incompatible edits from multiple worktrees when integrating source changes. - Decisive decision or feedback right: first-party capacity governor selects eligible queued Job claims and defers saturated sessions; an appropriately equipped coordinator model can then respond to a typed mergeconflict/notfastforward result by revising or deferring an integration. - Decision owner: deterministic Job governor for scheduling/capacity settlement; configured coordinating Agent for the optional subsequent worktree-repair decision, not an automatically present global LLM mediator. - Supporting / enforcement mechanisms: durable Job admissions, claimnext oldest-eligible selection, per-session/global capacity, lease/worker lock, worktree lifecycle states, conflict-returning mergeworktree, and joboutput/worktree tools. - Closure path: conflicting Job demand is admitted/queued; saturated sessions are skipped until slots release, and an eligible peer eventually starts with fresh execution context. In the optional worktree mode, conflicting source branches remain active on typed failed merge; the caller receives the error and can ask its agent to change/retarget work before reattempt. - Boundary reachability: both concurrent Jobs and worktree operations are registered, exercised first-party execution paths; component tests cover skipping an older saturated session, dual claim prevention and failed merge preserving active worktree. This is a composable coordination relation, not evidence of an automatic model conflict-resolution team on all fresh installs. - Why this is / is not agent-owned: the affected units are individually model-backed S1 branches, while the attenuation is primarily an implemented deterministic subsystem. C credits this cross-S1 facility and optional model composition; it does not claim S2=A autonomously negotiates conflicting task intentions. - Distinct S1 units: independent model-backed subagent or saved Agent conversations whose Jobs can be live concurrently. - Inter-S1 disturbance: actual global/session execution saturation and competing edits from distinct worktrees, not abstract task ordering. - Attenuating coordination relation: capacity reservations/eligibility prevent exceeding limits, skip one saturated session to make another eligible, and worktree isolation plus typed merge failure prevents blind overwrite during integration. - Feedback into subsequent S1 behaviour: released capacity starts the next Job; failed worktree merge preserves the branch and exposes its error to the agent/tool caller so subsequent S1 work can repair before merging. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the governor&#39;s admission decisions explicitly depend on cross-Job capacity interference and the worktree merge path explicitly represents cross-edit collision; mere sendmessage, a shared DAG or parallel queries are not credited. - Evidence: cross-session claim loop and limits, conflict feedback/active branch retention, dispatch tests, worktree failure tests. - Basis: first-party dispatcher, worktree manager and executable component tests. - Confidence: medium-high for bounded mechanical conflict attenuation; low for an unconfigured agent-driven negotiation loop. - Caveats: path warnings outside worktree are not a hard sandbox, and Git itself performs the merge. Capacity scheduling does not semantically detect two tasks editing the same path. The optional model retry is a possible feedback response, not an observed autonomous repair success.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C - Function: in a configured coordinator mode, maintain an owner-workspace view of current work, agent status and Jobs, select next responsibility and reassign/delegate based on returned work status. - Disturbance / variety regulated: overdue/in-flight work, idle specialist conversations, blocked tasks, active/queued Jobs, failed handoffs and changing immediate user priority. - Decisive decision or feedback right: the Coordinator/Chief of Staff model may read open work and current agent/job state, decide assignment or next task and send a bounded handoff; recipient execution and reply flow back into later coordinator turns. - Decision owner: owner-selected coordinating Agent model; human enables always-on and chooses its permissions/mission; Job governor enforces but does not choose project priorities. - Supporting / enforcement mechanisms: saved Coordinator and Chief of Staff system/tool configurations, listagents, openwork, listjobs/joboutput, handoff/sendmessage, always-on wake/check-in and return notices, persisted Goal/Job status. - Closure path: a live status or scheduled wake enters the coordinator conversation; it reads available work and cross-agent status, selects next owner/step and sends an authorized handoff; target executes in its independent Agent context and sends a completion reply, which alters the next current-control view. - Boundary reachability: the shipped createbuiltinagents installs roles with planning/status/delegation tools; owner can enable a saved Agent&#39;s always-on mode; handoff and Job return are implemented with recovery and loop limits. Neither an installed template nor a default disabled ticker automatically proves every instance runs that coordinator. - Why this is / is not agent-owned: current cross-work allocation is decided by a configured model rather than by a fixed queue; C reflects opt-in composition and limited scope rather than a universally active autonomous S3 manager. - Whole-system current view: for the owner-selected Agent portfolio, open work, addressable conversations, in-flight Job state and returned status; not an external organization&#39;s finances or all agents on other users&#39; instances. - Current-control decision scope: prioritization and delegation among current user-visible jobs, targeted recovery/escalation and reporting, bounded by saved Agent permissions and owner instructions. - Evidence: Coordinator and Chief of Staff built-ins, built-in installation, durable handoff and reply, always-on wake loop. - Basis: first-party configurable role registry and execution feedback; component tests of handoffs and wake turns. - Confidence: medium for the constructed S3 control loop; default-runtime universal coverage is explicitly not claimed. - Caveats: resource-capacity governor alone is not model-owned S3, and current delegated task summaries are not independent audit. All built-in always-on roles begin disabled; owner must configure and activate the relevant mode.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: optionally attach a separate read/test-only PR Verifier Agent to inspect a producer&#39;s actual work and return a corrective verdict to the coordinating/producing conversation. - Disturbance / variety regulated: a producer&#39;s untested, incorrect or misleading completion claim may otherwise be accepted from its own status summary. - Decisive decision or feedback right: the separate PR Verifier model reads the specification, code/diff and real test outputs, then returns ship, fix first or reject and numbered findings; parent/producer may decide corrective work. - Decision owner: separately configured verifier conversation for the judgment; parent agent/operator for what action to take on findings, not a hard automated PR merge veto. - Supporting / enforcement mechanisms: distinct pr-producer/pr-verifier built-in AgentSpecs, verifier allowlist without write/edit tools, handoff/return-reply, named conversation/branch, worktree list and read/terminal access. - Closure path: producer records work and requests a separate verifier handoff; verifier reads actual shared project files and runs checks independently of the producer&#39;s narrative; its reply arrives back at the sender for rework or operator delivery. - Boundary reachability: the installed verifier has explicit read/test permissions and no write/edit tools, and real first-party handoff transport returns a separate Agent&#39;s result. This is composable when invoked; there is no default mandatory reviewer before a Git merge or update. - Why this is / is not agent-owned: independent evaluation belongs to a different model-backed conversation with separate tool rights. A model merely summarizing its own tests or the deterministic update installer verifier alone would not establish this claim. - Claim being audited: the producer&#39;s assertion that a change implements the handed specification and passes its tests. - Ordinary reporting path: producer&#39;s task completion, change summary and claimed test results, as received by its parent. - Complementary access path: verifier can inspect files/diff through read and code-navigation tools and invoke read-only test commands via shell, without relying only on producer&#39;s summary. - Independence boundary: separate AgentSpec, conversation/turn and read-only allowlist; not a different GitHub organization, independent account, trusted third-party audit, or a proven mutually untrusted sandbox. - Who acts on findings: configured coordinating agent, producer on a subsequent task, or local human owner receives the returned verdict and may request correction or block delivery. - Evidence: producer vs verifier roles and allowlists, returning handoffs, handoff end-to-end test, independent self-update controller boundary as separate non-agent safety evidence. - Basis: constructed separate reviewer path plus source-level code/tests; no observed live LLM reviewer run or enforced reviewer acceptance gate. - Confidence: medium for configurable complementary access; low for automatic per-change independent assurance. - Caveats: role prompt forbids editing but a permitted bash may alter files; independent read/test intent is not a sandboxed read-only process guarantee. The distinct self-update verifier is deterministic controller-side verification, not automatically an S3 model auditor for every user task.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no verified closed agent-owned chain that senses external future change, selects a strategic capability/market option and returns that choice as an enduring adaptation of the managed agent organization. - Disturbance / variety regulated: future tools, models, changing external knowledge and workflow requirements could require adaptation, but inspected functionality does not establish the full strategic closure. - Decisive decision or feedback right: no single first-party, reachable, closed prospective option-selection right identified. The Research Desk may search current sources and report; arbitrary agent code edits may create new tools, but they are not automatically coupled into a future-intelligence decision loop. - Decision owner: owner/configured agents decide what to research or edit, with ultimate option integration normally requiring task instructions or user permission. - Supporting / enforcement mechanisms: optionally always-on Research Desk, websearch/webfetch, persistent Memory, first-party program hot-loader/self-programming methods, manually editable AgentSpecs. - Closure path: external updates can reach research briefs and user/agent actions; however the shipped role and tool wiring does not guarantee a future-oriented choice that changes strategy/capability and then verifies the enduring return to execution. - Why this is / is not agent-owned: external browsing is sensing, reusable self-programmed methods are extensibility and current S1 programming; their existence in the same repository is not proof of a separate S4 cycle. - Evidence: Research Desk prompt/tool role, opt-in always-on scheduler, Agent method registration, ordinary agent class. - Basis: supported role/module source plus explicit absence of a coupled strategic decision/return path. - Confidence: medium within default and declared always-on modes; does not rule out a user-composed S4 program. - Caveats: the README&#39;s self-evolution and proactive-agent promises are not treated as proof of completed outside/then organizational learning.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: owner-controlled, durable change of the saved Agent&#39;s constitutive instructions, identity, permissions and standing goal, with the updated configuration read into subsequent execution. - Disturbance / variety regulated: conflict between an Agent&#39;s persistent purpose/permission boundary and the owner&#39;s desired identity or authorization regime, not a one-off shell approval. - Decisive decision or feedback right: local human owner may edit/revoke Agent configurations and decide whether a specialist can act, research or send externally; Agent cannot legitimately grant itself unrestricted policy rights. - Decision owner: parent local user/administrator of the OpenProgram workspace; the Model and settings UI can suggest/configure but are not a new autonomous S5 authority. - Supporting / enforcement mechanisms: versioned saved AgentSpec configuration, agentregistry.manager.update, selected tool allowlists, alwayson enabled/autonomy/goal fields and permission-mode enforcement, tool resolution into runtime request. - Closure path: authorized owner changes saved Agent policy/identity; registry stores the edited spec; later selected Agent calls resolve the updated tool/system instructions and execute under the new policy. A deleted built-in is not silently recreated on restart. - Boundary reachability: the normal installed UI/API exposes saving/updating AgentSpecs; the same registry is used to construct future Agent runtime and tool policy. This is a human P mode, not S5=A agent self-constitutional authority. - Why this is / is not agent-owned: ultimate legitimate acceptance is a human choice; autonomous delegated task reassignment or self-programming cannot, by itself, rewrite the top-level owner&#39;s authority. - Identity / ultimate-policy issue: persistent AgentSpec instructions/allowlist and alwayson.autonomy define what a named Agent is allowed and tasked to do across turns, distinct from a single conversation response. - Ultimate authority in each claimed mode: local human owner is the only credited ultimate actor; the configured agent remains subordinate even if able to propose changes. - Return-to-operation path: manager.update persists the edited AgentSpec, and Agent.calloptions/runtime tool resolution uses the spec when the Agent runs again. - Evidence: saved configuration schema, config update, built-in deletion and edit persistence, AgentSpec policy resolution into calls. - Basis: first-party persisted config source and operating endpoint architecture. - Confidence: medium-high for genuine human-controlled persistent Agent identity; no model-origin constitutional proposal/independent appeal workflow is claimed. - Caveats: updating a child Agent task prompt is usually ordinary S3 delegation, not S5. Credit applies narrowly to authorized durable changes of the governing Agent&#39;s own identity/rules, not to OpenProgram maintainers editing GitHub source.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c53852df302ccf9fe3ef533635d16b6611a6879a/assessments/op/openprogram.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c53852df302ccf9fe3ef533635d16b6611a6879a\">c53852d &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"3\" data-assessment-at=\"2026-11-08T16:07:10+03:00\"><th scope=\"row\"><a href=\"https://github.com/rainyZhou2/SreAgentHarness\" target=\"_blank\" rel=\"noopener\">go-sre-harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>3</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-08\">2026-11-08</time></td><td class=\"review-ref\"><a href=\"https://github.com/rainyZhou2/SreAgentHarness/tree/218c2ce880cbbda33df6464b78aef96d201be913\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 218c2ce880cbbda33df6464b78aef96d201be913\">218c2ce &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: model-directed incident investigation through plans, hypotheses and tool calls, with observed system state and errors feeding the next reasoning step. - Disturbance / variety regulated: novel user incidents, unknown root cause, heterogeneous SRE tools, contradictory evidence, tool failure and interrupted/retried attempts. - Decisive decision or feedback right: configured cognitive/LLM strategy selects hypothesis, tool call and next reasoning step; a model planner may choose a runnable flow and revise it after failure. - Decision owner: active model-backed strategy/planner inside the worker, constrained by tenant policy; scripted strategy is a deterministic smoke mode and is not counted as model autonomy. - Supporting / enforcement mechanisms: Run/Step/Attempt transactional ledger and leases, strategies, prompt manifest, model gateway, policy gate, ToolCall, flow compiler, retries, memory retrieval, evidence refs and tool observations. - Closure path: incident goal is persisted; worker obtains a fenced step lease and assembles context; model selects a real tool or conclusion; tool executes after safety/approval evaluation, writes output, and the next leased reasoning step can adjust hypotheses, plan or finish. - Boundary reachability: normal server/local entrypoints initialize the worker with cognitive strategies, tool registry, gateway and planner; a configured model and granted external tools reach the real execution path, while local scripted strategy can demonstrate plumbing only. - Why this is / is not agent-owned: action/hypothesis choice is model-cognitive rather than authored runbook; policy and transactional persistence constrain/record, but do not choose the agent&#39;s investigative next action. - Evidence: agent loop, loop safeguards and tool result, model/planner strategy, flow child execution. - Basis: pinned first-party Go source and declared entrypoints; no compiled/runtime or credentialed model E2E. - Confidence: medium-high for reachable source-level execution; operational correctness unverified. - Caveats: a rule-based run without an LLM does not prove an autonomous S1 choice; the source has no Go unit tests, and the available environment has no go compiler.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: prevent several independently operating incident agents from exceeding an operator-defined shared-tool/target action budget, and return typed denial feedback for subsequent reasoning. - Disturbance / variety regulated: separate run/child agents attempting repeated restarts/side effects against the same target within a tenant or exhausting concurrent worker capacity. - Decisive decision or feedback right: an optional rate policy consults shared tenant action-intent history for a tool/target/window and applies configured deny or approval; pool/lease mechanics additionally prevent over-admission of active execution. - Decision owner: operator-authored RuleEngine and deterministic policy/work scheduler; an executing model can react to the refusal but has no right to relax the floor. - Supporting / enforcement mechanisms: per-target/per-tool Rate match and PostgreSQL/local CountActions, fail-closed history errors, action-intent ledger, policy gate, resource pool, serialized branch writer, typed refusal observations. - Closure path: first incident Run commits a relevant action intent; a concurrent second Run asks for the same tool/target; the shared counter reports the activity, rule matches threshold and gates action; denial/approval requirement returns to the second agent&#39;s next step. Activity ages out of the rule window, so later executions can become eligible. - Boundary reachability: RuleEngine.EvaluateRequest is a runnable gate and store implementations count persisted tenant intents; tenant policy configuration may enable rate.per=&quot;target&quot;. This is not a claim that a default fresh install has a protective rate rule for every SRE tool. - Why this is / is not agent-owned: C credits an implemented but configured cross-S1 interference/feedback mechanism; it is not A because the system does not evidence autonomous model negotiation of contention policies. - Distinct S1 units: separately executing incident Runs and flow-child model agents within the same tenant, sharing SRE action targets. - Inter-S1 disturbance: risk of repeated real side effects on the same service/target within one time window, caused by multiple agents (the mechanism also works with one agent). - Attenuating coordination relation: shared target-scoped action count conditions the second action gate on the first agent&#39;s recorded intent, reducing repeated/colliding tool effects. - Feedback into subsequent S1 behaviour: denial/approval status and reason are returned as a refused action in the model&#39;s observation stream; operator approval or elapsed time changes future eligibility. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: rate.per=&quot;target&quot; explicitly inspects real overlapping tool/target history across all tenant runs rather than merely passing messages, serializing one child or applying unrelated safety checks. - Evidence: target-aware rate contract/counter, rate-rule evaluation, shared SQL count, refusal feedback. - Basis: first-party code-level cross-run rule and durable ledger; no collision experiment executed. - Confidence: medium: explicit source-specific path but behavior depends on configured policy and functioning persistent store. - Caveats: rate windows are not atomic reservations against two concurrent first intents; both may pass before either records intent. Tenant-level policy protects only matching configured tool/targets and does not prove universal S2 negotiation.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C - Function: retain an instance-wide current view of lease/run/approval queue liveness and automatically recover stalled operations while preserving the worker and policy contract. - Disturbance / variety regulated: lost messages, worker crashes/expired leases, stuck conversation branches, stale queues and expired approval requests across simultaneously active incident runs. - Decisive decision or feedback right: first-party Reconciler.Tick reads global persistent state and decides which expired leases/approvals/stalled branches to reactivate or expire; an instance pool caps active work independently of model suggestions. - Decision owner: deterministic owner-instance reconciler and configuration, not a demonstrated LLM portfolio executive; user/operator owns the parameters. - Supporting / enforcement mechanisms: database Run/Step state, expired lease recovery, approval expiration, stalled-branch activation, stale run rewake, pool semaphores and notifications/outbox. - Closure path: durable state and timeouts make blocked/stale runs visible to the periodic reconciler; it returns leases to recoverable state, expires approval, wakes a run/branch and reconnects the next worker step to the same run ledger. - Boundary reachability: server app initializes the scheduler/reconciler in the normal service mode; the implementation operates on all relevant store runs for an instance, not a test-only runbook. - Why this is / is not agent-owned: first-party live control is deterministic and bounded; C is a composable organizational current-control facility, not S3=A model choice over enterprise priorities. - Whole-system current view: store-wide run leases, approval expirations, queued and stalled branch state inside the configured tenant/server boundary; excludes external production estate health, personnel or business portfolio. - Current-control decision scope: recovery/expiration/re-dispatch and per-process capacity, not redefinition of incident strategy, global budget allocation or policies. - Evidence: reconciler sweep, concurrency backpressure, durable state recovery. - Basis: first-party service code and durable semantics; no service-level restart fault-injection performed. - Confidence: medium-high for bounded S3-like runtime control, low for model-managed all-incident resource decisions. - Caveats: distinction from S2: S3 here reconciles the whole current execution state, not conflicts between two specific operational cells. A service monitor does not establish human-equivalent governance autonomy.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: check an agent&#39;s final incident claims against actual cited observations using a kernel-owned rule layer, with an optional separate model judge and bounded corrective backtracking. - Disturbance / variety regulated: unsupported self-declared incident resolution, fabricated citations, references to failed tool calls, inconsistent verification and conclusion/evidence mismatch. - Decisive decision or feedback right: verifier decides SUPPORTED/INSUFFICIENT/CONTRADICTED from a canonical evidence map; configured distinct judge may perform semantic support checks without being given the original agent&#39;s prompt/history; kernel can return a challenge step to the producing model. - Decision owner: non-agent rule verifier by default and optional independent model judge; kernel for backtrack/action decision, not the producing strategy. - Supporting / enforcement mechanisms: verify.Verifier, ModelJudge with a separate alias/prompt, canonical citation resolver, internal conclusionreview follow-up, bounded MaxBacktracks, durable independentverification report and reasoning score gating. - Closure path: final task decision exposes structured claims; kernel reconstructs cited evidence from real observation refs, verifier evaluates it; on insufficient/contradicted status and remaining budget, a kernel-owned challenge returns issues to S1 reasoning and revised claims can be checked again. Otherwise report persists with an unsupported outcome. - Boundary reachability: normal server internal/app defaults HARNESSREASONINGVERIFY=true, and local runtime installs the rule verifier; setting HARNESSVERIFIERMODELALIAS adds a separate model judge. Hence C covers both genuine compulsory mechanical check and explicitly configured complementary model path, not a claim of always-on independent semantic LLM audit. - Why this is / is not agent-owned: generator cannot grant its own claim status; a configured separate model may apply actual semantic judgment. Default rule-only citation check is deterministic and could not alone warrant S3=A. - Claim being audited: the final agent-reported VERIFIED/REFUTED incident hypotheses and cited evidence supporting diagnosis/conclusion. - Ordinary reporting path: producing strategy&#39;s structured decision/hypotheses and summary, including its own claimed verification and cited refs. - Complementary access path: kernel independently resolves canonical refs to recorded tool observations, evidence and memory available in the run ledger; optional judge reads those observations under a distinct prompt and model identity. - Independence boundary: separate verifier code and optional judge model call from the producer; uses the same source-observation corpus (not direct independent re-probing of external environment), and is configurable/disableable by the operator. - Who acts on findings: kernel inserts hidden conclusionreview challenge to producer within backtrack budget; saved report/metrics also inform operator and profile quality gate. - Evidence: verifier contract/rules, separate judge, kernel corrective loop, default and optional app wiring. - Basis: implemented return-to-producer code and separate-model mode; no live independent review result witnessed. - Confidence: medium-high for code-level closure; stronger claims of verifier truthfulness are unsupported by testing here. - Caveats: canonical citation existence is not external truth, and a separately prompted judge sharing the same evidence corpus is only bounded independence. The repository contains no Go tests to independently corroborate runtime execution.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S4 / adaptation: - State: P - Function: operator-led prospective improvement of future incident-handling capability through frozen real-run datasets, candidate profile variants, offline evaluation, holdout gates, measured canary and return to active profile. - Disturbance / variety regulated: changing external incident mix/service reliability and observed mismatch between current agent behavior and future target quality, failure rate, tool safety or cost. - Decisive decision or feedback right: owner/proposer chooses a candidate future profile version; non-inferiority gate compares candidate vs historical baseline and forbids failed promotion; a distinct approving human authorizes canary, the monitor auto-rolls back detected regressions, and owner chooses promotion. - Decision owner: legitimate local operator/approver for strategic option proposal/adoption; deterministic replay gate and canary monitor control test and rollback. No autonomous S4=A external trend strategist is claimed. - Supporting / enforcement mechanisms: dataset recording from actual runs, frozen holdout evaluation, profile candidate versioning, Gate thresholds, Approve anti-self-approval, percentage-bucketed canary rollout, control/canary stats and continuous rollback monitor. - Closure path: real incident-run outcomes/feedback become dataset cases; owner proposes candidate to improve future SRE responses; baseline/candidate replay produces gate evidence; different authorized approver accepts; routed future Runs exercise canary, with rollback on breach; successful owner promotion sets the new active profile version used by subsequent Runs. - Boundary reachability: internal/eval.Service implements all transitions, ResolveProfile routes real new Runs to canary/active versions, and API offers candidate/evaluation/approval/rollout operations; this is a supported human-parent improvement mode, not merely a README suggestion. - Why this is / is not agent-owned: an operator supplies the future option and authority to promote; automatic evaluation/rollback are supporting tests. P avoids assigning a strategic choice to the diagnostic LLM. - External distinction: incident outcomes and operator feedback originate from real monitored SRE services outside the harness&#39;s own model loop; frozen evaluation cases preserve these past external disturbances rather than generating synthetic internal tests alone. - Future / prospective distinction: a proposed candidate is assessed against a frozen holdout before it handles future incidents, and canary groups measure whether a prospective new configuration should become the next active operating default. - Adaptation option generated: a human operator/proposer supplies a new version of evolvable model, reasoning, memory or planner configuration, judged against holdout baseline and released only after a distinct human gate; there is no autonomous option inventor credited. - Path back into current capability / S3: StartCanary/ResolveProfile makes new Runs use the candidate profile percentage; Promote changes active profile for subsequent S1 Runs, while MonitorTick protects current S3 control by quarantining and rolling back regressions. - Evidence: real-run dataset recording, candidate replay/gate, separate human approval and canary, promotion and active routing, rollback monitor. - Basis: first-party persisted candidate/evaluation/canary implementation and return-to-operation controls. - Confidence: medium for supported human-guided future adaptation; no empirical dataset/canary deployment witnessed. - Caveats: dataset replay and regression monitoring do not independently sense geopolitical or strategic future. No model-origin selection of an outside future option is established. The README&#39;s phrase &quot;evolution loop is complete&quot; is read only as bounded product-level parent-guided capability improvement.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: operator-governed versioned policy/authority of the SRE agent profile, maintaining a non-relaxable risk floor and controlling when identity-critical tools/policies change across future Runs. - Disturbance / variety regulated: proposed efficiency/evolution changes that would weaken safety policy, permit destructive R3 actions or change an agent&#39;s enduring tool/authorization identity without legitimate authority. - Decisive decision or feedback right: human operator creates/edits immutable versioned profiles and must authorize frozen identity fields; evolution candidates cannot modify tools, approval policy, risk overrides, allowed aliases, strategy or flow; framework policy floor forbids R3 and requires approval for R2. - Decision owner: tenant administrator/legitimate human owner and enforced framework floor, not individual incident-solving agent or arbitrary extension plugin. - Supporting / enforcement mechanisms: profile.Spec frozen/evolvable distinction and ApplyPatch reject rules, policy.Guarded safety floor, identity-bound plan/action approvals, profile version pinning, tenant permissions and audit ledger. - Closure path: owner changes constitutive profile in permitted profile-creation/update pathway; a new immutable version persists, a Run pins the authorized version, and the worker&#39;s effective tool/policy scope is rebuilt under it. A candidate aiming to change a frozen field fails rather than silently changing the ultimate rules. - Boundary reachability: profile APIs and app are real entrypoints; profile.Spec is passed to worker tool/policy resolution, and the guard is composed around custom policy. The claimed P mode is a human-parent governing boundary, not autonomous S5=A. - Why this is / is not agent-owned: ultimate identity/prohibition belongs to the operator/framework. The agent may optimize cognitive parameters but cannot authorize itself to relax safety-critical frozen fields. - Identity / ultimate-policy issue: enduring agent&#39;s allowed tools, safety risk classes, approval requirements, strategy and immutable flow are constitution-level profile boundaries, distinct from approving an individual action intent. - Ultimate authority in each claimed mode: authorized human/operator plus non-bypassable safety floor; no independent agent&#39;s power to rewrite its own policy. - Return-to-operation path: new authorized profile version is persisted and pinned into subsequent Run creation; policy floor applies to every later tool intent. - Evidence: operator-owned profile and frozen fields, non-bypassable policy floor, human separate approval, profile API. - Basis: versioned schema, executable policy floor and owner-facing API code. - Confidence: medium-high for structural human authority and return, not for live compliance reliability. - Caveats: approving one risk-R2 command is S1 safety governance, not by itself S5. Only durable changes to the governing profile/identity plus non-relaxable floor support S5=P here.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9599f5d3766b568e88a3d0f18c8d1a7853518fb6/assessments/go/go-sre-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9599f5d3766b568e88a3d0f18c8d1a7853518fb6\">9599f5d &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-11-05T21:40:17+03:00\"><th scope=\"row\"><a href=\"https://github.com/bhandiwad/agent-harness\" target=\"_blank\" rel=\"noopener\">Pandita Agent Harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/bhandiwad/agent-harness/tree/0827a48d5131537216e74cabd2acf78f0138686b\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 0827a48d5131537216e74cabd2acf78f0138686b\">0827a48 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Model-directed task execution and conversational/file/tool work with successive observations. - Disturbance / variety regulated: User changes, variable model output, local file contents, tool errors, context and permission limits. - Decisive decision or feedback right: The model chooses a tool name/arguments, delegates to an allowed specialist or returns a final answer; subsequent tool receipts can alter its next choice. - Decision owner: The configured assistant model, within operator-set tool schemas and permission bounds. - Supporting / enforcement mechanisms: Durable session/turn history, PostgreSQL writer lock, budgets, installed adapters, native tools, separate approver and receipt validation. - Closure path: User turn → model generation → selected tool or final response → verified tool result/feedback appended → next agent model step or terminal answer. - Boundary reachability: The shipped Runner.tick and modelstep are wired from the installable worker and current config/agent.json gives the assistant selectable native file tools; a real provider endpoint must be configured by the operator. - Why this is / is not agent-owned: Removing the model leaves authorization and state transitions, but no discretionary interpretation of the user task or choice among tools; hence S1 choice is agent-owned. - Evidence: installed config, model/tool loop, dispatch. - Basis: structural. - Confidence: High for first-party wiring, not for untested live model behavior. - Caveats: Endpoint/keys and tenant authorization need real deployment; API limits and approval are external constraints, not autonomous owner rights.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No shipped closed attenuation relation between distinct concurrently operating S1 organizations is demonstrated. - Disturbance / variety regulated: Potential conflicting specialist work or concurrent session writes; team handoff data and writer locking address different local hazards. - Decisive decision or feedback right: No distinct inter-S1 coordination actor decides a response to concrete peer conflict; fixed team order and single-session concurrency prevent local overlap. - Decision owner: Root S1 chooses permitted delegation; deterministic session code serializes handoffs. - Supporting / enforcement mechanisms: Specialist team sequence, parent frames, Postgres writer lock and configured active-session capacity. - Closure path: Root task → specialist result → root context; no peer-interference observation → coordination judgment → revised independent S1 commitments loop. - Why this is / is not agent-owned: Sequencing a hierarchy and blocking concurrent writes do not by themselves establish independent S1-unit oscillation regulation. - Evidence: team handoff/return, session ownership, storage. - Basis: structural bounded absence. - Confidence: Medium-high. - Caveats: A tenant could build a fleet with external coordination; no S2-specific packaged correction relation was established here.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No separately owned whole-system current-control function over a portfolio of autonomous operations is established. - Disturbance / variety regulated: Session concurrency, budget exhaustion, cancellation, uncertain external writes and approval delays. - Decisive decision or feedback right: Configuration/tenant owner sets limits and agent roster; runtime enforces caps and halts risky states, rather than autonomously revising whole-system resource/commitment priorities. - Decision owner: Operator/developer for configuration and human approver for action permission; model for its own S1 task steps. - Supporting / enforcement mechanisms: maxsteps/tokens/time, session locks, access-control checks, approval digest and reconciliation guard. - Closure path: Fixed limit violation → fail/pause/deny/reconcile; no evidenced autonomous or legitimate parent current-control bargaining and returned cross-unit decisions. - Why this is / is not agent-owned: Removing the model leaves static limit enforcement, not a discretionary portfolio-control decision. Team delegation is task decomposition, not S3 by name. - Evidence: config and capacities, run limits/recovery, approval/receipt enforcement. - Basis: structural bounded absence. - Confidence: Medium-high. - Caveats: A broader tenancy operation may have S3 outside this agent-service boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No default complementary, sufficiently independent audit of operational claims is wired into a corrective governance path. - Disturbance / variety regulated: Incorrect answers, unconfirmed tool side effects and fabricated completion. - Decisive decision or feedback right: The optional completioncheck callback can reject format/content against a developer-supplied checker; tool receipts confirm transport outcomes, but no first-party separate reality-inspecting auditor makes an independent judgment. - Decision owner: Configured callback/adapter and deterministic runtime for validation; no S3 audit owner established. - Supporting / enforcement mechanisms: Tool result schema checks, write receipts, completion schema/check callbacks, test suite and event log. - Closure path: Model answer → optional direct callback → retry/fail, or tool invocation → receipt → model; this is routine completion/tool validation, not complementary audit access to independent operational reality. - Why this is / is not agent-owned: An injected callback can be implemented by an external evaluator, but no shipped audit-specific independent actor/path is present or owned by a first-party standard mode. - Evidence: completion check and rejection, tool receipt validation. - Basis: structural bounded absence. - Confidence: Medium-high. - Caveats: An application can install an independent checker, but generic callback extensibility alone does not supply a first-party S3 mode.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No closed external-and-prospective adaptation cycle for future harness capability is installed. - Disturbance / variety regulated: Changing model providers, tools, user needs and knowledge; context windows and new requirements. - Decisive decision or feedback right: User/developer changes the model/tool configuration and prompts, while agent research occurs only within the current request. - Decision owner: Operator/developer for future capacity; same S1 model for present task response. - Supporting / enforcement mechanisms: Configured model aliases, skills, context history/archive, provider protocol adapter and optional specialist handoff. - Closure path: Manual config changes can affect later execution; no product-owned future-environment sensing → adaptation option judgment → feedback into present S3/capability. - Why this is / is not agent-owned: Context/history retention and task planning optimize current work; they do not authorize an agent to revise its organizational future capability. - Evidence: settings and agent contracts, context construction, installed config. - Basis: structural bounded absence. - Confidence: High. - Caveats: Separate maintenance-agent examples do not automatically wire future adaptation into the deployed generic assistant.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No first-party identity/ultimate-policy dispute resolution loop at the assessed agent-service recursion. - Disturbance / variety regulated: Access violations, disallowed tools, untrusted input and action approval. - Decisive decision or feedback right: Tenant operator and external identity authority supply authorizations and policy; independent actor approves a particular write action, not ultimate organizational identity. - Decision owner: External operator/IdP/approver for fixed permissions; none for a packaged S5 function. - Supporting / enforcement mechanisms: RS256 identity verification, role permissions, immutable configuration digest, approval digest and untrusted-input isolation. - Closure path: Token/policy match → permitted/denied session/tool; action approval returns one tool gate, not an identity-level dispute → legitimate authority decision → enduring operating-policy return. - Why this is / is not agent-owned: Agent instructions explicitly treat tool output as data and cannot change policy authority. Human approval is narrow execution consent, not S5. - Evidence: authorization and config digest, approval logic, policy/identity config. - Basis: structural bounded absence. - Confidence: High. - Caveats: A separate operating institution may exercise S5 outside the declared product boundary.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ce4965715a8d34e1ca0c4292be0cfa66387ff968/assessments/pa/pandita-agent-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ce4965715a8d34e1ca0c4292be0cfa66387ff968\">ce49657 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-11-05T20:45:47+03:00\"><th scope=\"row\"><a href=\"https://github.com/cUDGk/nipus-harness\" target=\"_blank\" rel=\"noopener\">nipus-harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/cUDGk/nipus-harness/tree/0c0349ee7f37d9bc0334c1d5ea7802c49f8e950b\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 0c0349ee7f37d9bc0334c1d5ea7802c49f8e950b\">0c0349e &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: complete bounded coding/research work and correct it against actual tool/acceptance feedback. - Disturbance / variety regulated: unknown source, failed checks, scope violations, incomplete answers and transient model/tool errors. - Decisive decision or feedback right: choose inspections, edits, commands and repair strategy; declare finish or an evidenced blocker. - Decision owner: model worker instantiated by the first-party prompt/tool/continuation composition; optional declared child owns its bounded local work. - Supporting / enforcement mechanisms: Pi session/model library, owned tools, boxing, request gates, acceptance runner, result/evidence/diff validation, persisted sessions and ledger. - Closure path: goal → tool-backed worker → finish → real checks/evidence/scope → reasons returned to same worker → revised work or honest terminal result. - Boundary reachability: CLI createSession wires the owned customTools and prompt, then directly invokes runLoop; dependency execution does not replace this composition. - Why this is / is not agent-owned: removing the worker leaves checks/locks but no task-specific implementation or correction decisions. - Evidence: src/cli.ts; src/loop.ts; src/tools.ts; src/prompt.ts; src/session.ts; src/delegate.ts. - Basis: structural. - Confidence: high for source wiring; not an empirical outcome claim. - Caveats: Source reachability only; Windows/model prerequisites were not exercised. A mock provider is not credited as autonomous.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: prevent destructive overlap among independent task-worker runs sharing folders and host jobs. - Distinct S1 units: separate CLI task/worker runs with their own goal, session and result on the same host. - Inter-S1 disturbance: concurrent writers in an identical or nested workspace undo each other&#39;s edits; overlapping Unity/heavy processes contend for an exclusive host resource; crashed owners may leave orphan processes. - Attenuating coordination relation: CLI lockWorkspace uses a short atomic table lock plus real-path exact/parent-child checks before acquiring a writer lock; hostJob waits on named owner-aware locks, detects a busy Unity project and reaps stale-owner processes before reuse. - Feedback into subsequent S1 behaviour: workspacebusy prevents a second writer from starting; busy host jobs queue until safe or return busy at timeout into worker/acceptance feedback. The lock is released after the owning task/process ends. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the relations identify actual workspace/resource collision domains and modify whether/when another independent operational run may execute. - Disturbance / variety regulated: cross-run edit interference and exclusive host-process conflict. - Decisive decision or feedback right: admit, defer or reject conflicting runs under the fixed collision policy. - Decision owner: developer-authored lock/admission policy and caller-declared host lock identity; autonomous organizational coordination discretion is not composed. - Supporting / enforcement mechanisms: exclusive-create lock files, owner PID/start-time checks, workspace table, queue timeout, orphan cleanup and returned status. - Closure path: another active owner&#39;s collision → refusal/wait → subsequent run starts only after safe release or receives busy evidence. - Boundary reachability: src/cli.ts invokes lockWorkspace before work and releases it in finally; src/host.ts hostJob is reachable through declared tools and acceptance jobs. - Why this is / is not agent-owned: specific coordination machinery is shipped, but its response is predetermined rather than chosen/revised by an autonomous coordinator. - Evidence: src/host.ts; src/cli.ts; src/tools.ts; tests/parallel.test.ts; README.md. - Basis: structural. - Confidence: high for source wiring; not an empirical outcome claim. - Caveats: C does not claim coordination across hosts/installations or semantic negotiation. Tests were inspected as witnesses, not executed here.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: whole-system inside-and-now control - Disturbance / variety regulated: candidate variety and checked alternatives are recorded below. - Decisive decision or feedback right: no qualifying function-specific path established. - Decision owner: ordinary operational agent, developer and caller rights do not establish this distinct function. - Supporting / enforcement mechanisms: src/gate.ts, src/commands.ts, src/cli.ts, src/delegate.ts - Closure path: Per-role/run quotas, account-limit enforcement, static tool/model profiles and host locks bound tasks. status --active exposes state and stop/resume provides local lifecycle intervention, but no shipped whole-system commitment/resource decision with a distinct supervisory owner and return contract is established. Generic caller control is not automatically parent S3. - Why this is / is not agent-owned: positive and supported parent alternatives were tested before this bounded absence conclusion. - Evidence: src/gate.ts; src/commands.ts; src/cli.ts; src/delegate.ts. - Basis: structural. - Confidence: high for source wiring; not an empirical outcome claim. - Caveats: Bounded to the reviewed supported distribution; custom future extensions are not evidence of a shipped path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: complementary independent audit - Disturbance / variety regulated: candidate variety and checked alternatives are recorded below. - Decisive decision or feedback right: no qualifying function-specific path established. - Decision owner: ordinary operational agent, developer and caller rights do not establish this distinct function. - Supporting / enforcement mechanisms: src/loop.ts, src/rules.ts, src/delegate.ts, tests/review.test.ts - Closure path: runLoop checks acceptance, evidence and diffs as the normal completion path and sends failures back to the same worker. Suspect violations and needsjudgment do not instantiate an independent source auditor. Arbitrary declared roles can be composed into review but no audit-specific independent claim/judgment/corrective loop is supplied. - Why this is / is not agent-owned: positive and supported parent alternatives were tested before this bounded absence conclusion. - Evidence: src/loop.ts; src/rules.ts; src/delegate.ts; tests/review.test.ts. - Basis: structural. - Confidence: high for source wiring; not an empirical outcome claim. - Caveats: Bounded to the reviewed supported distribution; custom future extensions are not evidence of a shipped path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: external and prospective capability adaptation - Disturbance / variety regulated: candidate variety and checked alternatives are recorded below. - Decisive decision or feedback right: no qualifying function-specific path established. - Decision owner: ordinary operational agent, developer and caller rights do not establish this distinct function. - Supporting / enforcement mechanisms: src/cli.ts, src/session.ts, src/loop.ts, src/prompt.ts - Closure path: Web retrieval serves the current research goal; session persistence, retry and resume retain ongoing work. No supported outside-and-then option-development/adoption path changes the worker&#39;s future repertoire; task/model configuration edits are inputs, not a closed parent adaptation function. - Why this is / is not agent-owned: positive and supported parent alternatives were tested before this bounded absence conclusion. - Evidence: src/cli.ts; src/session.ts; src/loop.ts; src/prompt.ts. - Basis: structural. - Confidence: high for source wiring; not an empirical outcome claim. - Caveats: Bounded to the reviewed supported distribution; custom future extensions are not evidence of a shipped path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: identity and ultimate-policy closure - Disturbance / variety regulated: candidate variety and checked alternatives are recorded below. - Decisive decision or feedback right: no qualifying function-specific path established. - Decision owner: ordinary operational agent, developer and caller rights do not establish this distinct function. - Supporting / enforcement mechanisms: src/prompt.ts, src/cli.ts, src/gate.ts, src/loop.ts - Closure path: Fixed goals, task scope, forbidden terms, model/tool gates and clean-room declarations constrain operational execution. A blocked/needsjudgment result requests task-owner judgment, but no explicit ultimate identity/policy matter and authoritative return into standing governance is supplied. - Why this is / is not agent-owned: positive and supported parent alternatives were tested before this bounded absence conclusion. - Evidence: src/prompt.ts; src/cli.ts; src/gate.ts; src/loop.ts. - Basis: structural. - Confidence: high for source wiring; not an empirical outcome claim. - Caveats: Bounded to the reviewed supported distribution; custom future extensions are not evidence of a shipped path.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/83ba5c0624e2056ca6c034332624e473993f2f01/assessments/ni/nipus-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 83ba5c0624e2056ca6c034332624e473993f2f01\">83ba5c0 &#8599;</a></td></tr>"];
